with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('5cf427a8-b6c3-4e0a-a5cf-41afd12eb714'::uuid,ARRAY['{V/Adjective(い/な)/Noun+copula} て もいい']::text[],ARRAY['Use this construction to express may; it is okay to. Expresses permission.']::text[],ARRAY['【Antonym Expression: はいけない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:ここで煙草を吸ってもいいですか。 B:はい、いいです。","japanese_furigana":"A:ここで煙草を吸ってもいいですか。 B:はい、いいです。","english":"A: May I smoke here? B: Yes, you may."},{"japanese":"高くてもいい・いいです。","japanese_furigana":"高くてもいい・いいです。","english":"It is all right if it''s expensive."}]'::jsonb),
    ('69149182-17db-4697-a3ea-45d583f5895b'::uuid,ARRAY['(i) Vinformal negative なくて Where V is often a potential verb']::text[],ARRAY['Use this construction to express not doing/being and; because not. Negative て-form used to connect states or causes.']::text[],ARRAY['【Related Expression: ないで; ないから; ないので; なくても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"朝七時に起きられなくて会社に遅れた・遅れました。","japanese_furigana":"朝七時に起きられなくて会社に遅れた・遅れました。","english":"I couldn''t get up at seven and was late for work (at my company)."},{"japanese":"先生の説明が分からなくて困りました。","japanese_furigana":"先生の説明が分からなくて困りました。","english":"I didn''t understand the teacher''s explanation and had a difficult time."}]'::jsonb),
    ('debf2b3f-62a5-41ae-a005-5b0f4fd2feb1'::uuid,ARRAY['(i) {V/Adjective い} informal の']::text[],ARRAY['Use this construction to express the act/fact of; nominalizer. Turns a clause into a noun-like unit using の.']::text[],ARRAY['【Related Expression: こと2; の2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語を教えるのは難しい・難しいです。","japanese_furigana":"日本語を教えるのは難しい・難しいです。","english":"Teaching Japanese is difficult."},{"japanese":"私は雪子さんがビールを飲むのを見た・見ました。","japanese_furigana":"私は雪子さんがビールを飲むのを見た・見ました。","english":"I saw Yukiko drink beer."}]'::jsonb),
    ('39353520-bfe0-4d16-8c24-cba5b95d4b6d'::uuid,ARRAY['Canonical pattern: 〜は（主題）']::text[],ARRAY['Use this construction to express as for; topic marker. Marks the topic or a contrastive frame for the sentence.']::text[],ARRAY['【Related Expression: が】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は学生だ・です。","japanese_furigana":"私は学生だ・です。","english":"I am a student."},{"japanese":"杉田さんは行きますが私は行きません。","japanese_furigana":"杉田さんは行きますが私は行きません。","english":"Mr. Sugita will go (there) but I won''t go."}]'::jsonb),
    ('bf848a68-8d58-42e6-a4ef-d75444c20a6f'::uuid,ARRAY['Canonical pattern: あげる']::text[],ARRAY['Use this construction to express give. Giving verb viewed from the giver toward another person.']::text[],ARRAY['【Related Expression: くれる1; (もらう1)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は良子に花をあげた・あげました。","japanese_furigana":"私は良子に花をあげた・あげました。","english":"I gave Yoshiko flowers."},{"japanese":"大野さんは山本さんに本をあげた。","japanese_furigana":"大野さんは山本さんに本をあげた。","english":"Ms. Ono gave Mr. Yamamoto a book."}]'::jsonb),
    ('de8b867c-8c9b-4361-9e71-236ec77466ec'::uuid,ARRAY['Canonical pattern: くれる']::text[],ARRAY['Use this construction to express give me/us. Giving verb for something given to the speaker or speaker''s in-group.']::text[],ARRAY['【Related Expression: あげる1; もらう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大川さんは（私に）本を呉れた・呉れました。","japanese_furigana":"大川さんは（私に）本を呉れた・呉れました。","english":"Mr. Okawa gave me a book."},{"japanese":"ビルは（君に）何を呉れましたか。","japanese_furigana":"ビルは（君に）何を呉れましたか。","english":"What did Bill give to you?"}]'::jsonb),
    ('1e76f668-b7c2-4c62-8343-fcd71a7df1d7'::uuid,ARRAY['Canonical pattern: もらう']::text[],ARRAY['Use this construction to express receive. Receiving verb viewed from the recipient.']::text[],ARRAY['【Related Expression: くれる1 (あげる1)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"（私は）山本さんに本をもらった・もらいました。","japanese_furigana":"（私は）山本さんに本をもらった・もらいました。","english":"I got a book from Mr. Yamamoto."},{"japanese":"山川さんは橋本さんにウイスキーをもらった。","japanese_furigana":"山川さんは橋本さんにウイスキーをもらった。","english":"Mr. Yamakawa got whiskey from Mr. Hashimoto."}]'::jsonb),
    ('57209ea0-0246-4f0e-b589-26ec1cb9e84e'::uuid,ARRAY['普通形 + けれど／けど']::text[],ARRAY['Use to connect a clause to contrasting information or to soften/background what follows.']::text[],ARRAY['けど is more conversational; けれど and けれども are progressively fuller forms.']::text[],'[{"japanese":"行きたいけど、今日は時間がありません。","japanese_furigana":"[行|い]きたいけど、[今日|きょう]は[時間|じかん]がありません。","english":"I want to go, but I do not have time today."},{"japanese":"この店は小さいけれど、とても人気があります。","japanese_furigana":"この[店|みせ]は[小|ちい]さいけれど、とても[人気|にんき]があります。","english":"This shop is small, but it is very popular."}]'::jsonb),
    ('4de90cb3-dcab-40d9-8e97-01167b5f455c'::uuid,ARRAY['普通形 + 時に']::text[],ARRAY['Use 時に when identifying a particular time point at which an event occurs.']::text[],ARRAY['The particle に highlights the time point more explicitly than 時 without に.']::text[],'[{"japanese":"日本へ行った時に、友達に会いました。","japanese_furigana":"[日本|にほん]へ[行|い]った[時|とき]に、[友達|ともだち]に[会|あ]いました。","english":"When I went to Japan, I met a friend."},{"japanese":"困った時に、この番号に電話してください。","japanese_furigana":"[困|こま]った[時|とき]に、この[番号|ばんごう]に[電話|でんわ]してください。","english":"When you have trouble, please call this number."}]'::jsonb),
    ('d5ddd329-5a91-4a33-ba4e-388321005b6b'::uuid,ARRAY['Vます-stem + に + 行く／来る']::text[],ARRAY['Use a verb stem plus に with a motion verb to state the purpose of going or coming.']::text[],ARRAY['The motion itself is foregrounded, while the verb before に gives its purpose.']::text[],'[{"japanese":"駅へ友達を迎えに行きます。","japanese_furigana":"[駅|えき]へ[友達|ともだち]を[迎|むか]えに[行|い]きます。","english":"I am going to the station to pick up my friend."},{"japanese":"友達が日本へ遊びに来ました。","japanese_furigana":"[友達|ともだち]が[日本|にほん]へ[遊|あそ]びに[来|き]ました。","english":"My friend came to Japan to visit and have fun."}]'::jsonb),
    ('f77c5e9c-7d25-499c-8e15-37f0a204233b'::uuid,ARRAY['(i) Quotation と']::text[],ARRAY['Use this construction to express A particle which marks a quotation, sound or the manner in which someone/something does something.. A particle which marks a quotation, sound or the manner in which someone/something does something.']::text[],ARRAY['The core sense is A particle which marks a quotation, sound or the manner in which someone/something does something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ヒルさんは私に日本語で「こんにちは。」と言った・言いました。","japanese_furigana":"ヒルさんは私に日本語で「こんにちは。」と言った・言いました。","english":"Mr. Hill said to me in Japanese, “Hello!”"},{"japanese":"トムは日本へ行きたいと言っている。","japanese_furigana":"トムは日本へ行きたいと言っている。","english":"Tom says that he wants to go to Japan."}]'::jsonb),
    ('fa94eb9e-5c87-4bb1-94aa-8ca79fa5ad76'::uuid,ARRAY['(i) N(Prt) も N(Prt) も N(Prt) も']::text[],ARRAY['Use this construction to express The repeated use of a particle meaning ‘also’ to list elements belonging to the same part of speech.. The repeated use of a particle meaning ‘also’ to list elements belonging to the same part of speech.']::text[],ARRAY['The core sense is The repeated use of a particle meaning ‘also’ to list elements belonging to the same part of speech.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"田中さんも中山さんもデパートに勤めている・います。","japanese_furigana":"田中さんも中山さんもデパートに勤めている・います。","english":"Both Mr. Tanaka and Mr. Nakayama are working for a department store."},{"japanese":"京都へはバスでも電車でも行ける・行けます。","japanese_furigana":"京都へはバスでも電車でも行ける・行けます。","english":"We can go to Kyoto either by both bus or by electric train."}]'::jsonb),
    ('a7cae4c2-a1b0-47e9-aa3e-9b820a426a76'::uuid,ARRAY['(i) Noun も 私 も I, too/me (as direct object), too']::text[],ARRAY['Use this construction to express A particle which indicates that a proposition about the preceeding element X is also true when another similar proposition is true.. A particle which indicates that a proposition about the preceeding element X is also true when another similar proposition is true.']::text[],ARRAY['The core sense is A particle which indicates that a proposition about the preceeding element X is also true when another similar proposition is true.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私も学生だ・です。","japanese_furigana":"私も学生だ・です。","english":"I, too, am a student."},{"japanese":"私はスペイン語も話す・話します。","japanese_furigana":"私はスペイン語も話す・話します。","english":"I speak Spanish, too."}]'::jsonb),
    ('0d22c6e7-7a70-4e04-992f-596a1586f96c'::uuid,ARRAY['(i) {Vinformal/Vますたい} ものだ']::text[],ARRAY['Use this construction to express The speaker presents some situation as if it were a tangible object.. The speaker presents some situation as if it were a tangible object.']::text[],ARRAY['【Related Expression: から; のだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:どうして行かないの？ B:だって、忙しいもの。","japanese_furigana":"A:どうして行かないの？ B:だって、忙しいもの。","english":"A: How come you don''t go there? B: ''Cause I''m busy."},{"japanese":"よくあんな男とデート出来るものだ・です！","japanese_furigana":"よくあんな男とデート出来るものだ・です！","english":"How could you date that kind of guy!"}]'::jsonb),
    ('3d669607-bcf9-472e-8fd1-2979c355083f'::uuid,ARRAY['(i) Noun より']::text[],ARRAY['Use this construction to express A particle which indicates that something/someone is being compared with something/someone.. A particle which indicates that something/someone is being compared with something/someone.']::text[],ARRAY['【Related Expression: 方が~より】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語はスペイン語より（も）面白い・面白いです。","japanese_furigana":"日本語はスペイン語より（も）面白い・面白いです。","english":"Japanese is more interesting than Spanish."},{"japanese":"車で行くほうがバスで行くより（も）安い・安いです。","japanese_furigana":"車で行くほうがバスで行くより（も）安い・安いです。","english":"Going by car is cheaper than going by bus."}]'::jsonb),
    ('f89fdea6-aa2e-40f1-9b27-78d0f8379a63'::uuid,ARRAY['(i) Vvolitional ( っ ) たって']::text[],ARRAY['Use this construction to express The contracted form of と言っても or としても.. The contracted form of と言っても or としても.']::text[],ARRAY['【Related Expression: ようにも(~ない)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一人でしよう(っ)たって、それは無理だ。","japanese_furigana":"一人でしよう(っ)たって、それは無理だ。","english":"You''ll never be able to do it alone! (literally: Even if you try to do it alone, that''s impossible.)"},{"japanese":"今すぐ買いに行く(っ)たって、もう店はみんな閉まっている。","japanese_furigana":"今すぐ買いに行く(っ)たって、もう店はみんな閉まっている。","english":"Even if you wanted to go buy it right now, the stores are all already closed."}]'::jsonb),
    ('b162050f-ccfe-4d88-b6d2-4be509ee41ee'::uuid,ARRAY['(i) Vinformal past って']::text[],ARRAY['Use this construction to express The informal form of ても.. The informal form of ても.']::text[],ARRAY['【Related Expression: ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一人で旅行に行ったって面白くない。","japanese_furigana":"一人で旅行に行ったって面白くない。","english":"It''s not fun traveling (literally: if I travel) alone."},{"japanese":"私は少しくらい高く(っ)たって、質のいいものを買うことにしている。","japanese_furigana":"私は少しくらい高く(っ)たって、質のいいものを買うことにしている。","english":"I make it a rule to buy good quality things even if they are a little more expensive."}]'::jsonb),
    ('ba5912ad-eec1-454a-8ea0-6dba4f334250'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast ( と言 ) ってらない']::text[],ARRAY['Use this construction to express A phrase used to express a strong sensation or emotion.. A phrase used to express a strong sensation or emotion.']::text[],ARRAY['【Related Expression: 本当に; て仕方がない; て堪らない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"つまらないミスで試合に負けて悔しい(と言)ったらない。","japanese_furigana":"つまらないミスで試合に負けて悔しい(と言)ったらない。","english":"I''m so mortiﬁed because I lost the game due to a stupid mistake."},{"japanese":"老眼が進んで眼鏡なしでは近くの字が読めないので、不便(と言)ったらない。","japanese_furigana":"老眼が進んで眼鏡なしでは近くの字が読めないので、不便(と言)ったらない。","english":"My farsightedness has gotten worse so I can''t read words up close without my glasses—it''s so inconvenient!"}]'::jsonb),
    ('b920eb08-20c4-4ed9-9415-3582abfdce0a'::uuid,ARRAY['(i) Vinformal past 上で']::text[],ARRAY['Use this construction to express A compound particle that is used to express a preparatory action for a relatively important action.. A compound particle that is used to express a preparatory action for a relatively important action.']::text[],ARRAY['【Related Expression: てから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"よく考えた上で御返事いたします。","japanese_furigana":"よく考えた上で御返事いたします。","english":"I will reply upon careful consideration."},{"japanese":"話し合いの上で結論を出したいと思います。","japanese_furigana":"話し合いの上で結論を出したいと思います。","english":"I would like to draw a conclusion after discussion."}]'::jsonb),
    ('1b87c373-47f3-402e-a5a1-bcaae11e648f'::uuid,ARRAY['あながち ～ ない']::text[],ARRAY['Use this construction to express A structure that indicates that something is not necessarily the way the speaker/writer thought.. A structure that indicates that something is not necessarily the way the speaker/writer thought.']::text[],ARRAY['【Related Expression: 必ずしも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼の推理もあながち間違っていないのかもしれない。","japanese_furigana":"彼の推理もあながち間違っていないのかもしれない。","english":"His guess may not necessarily be wrong."},{"japanese":"バーチャル指揮者ソフトが売れているところを見ると、一度は指揮者になってみたいというのは、あながち僕だけの願望ではないらしい。","japanese_furigana":"バーチャル指揮者ソフトが売れているところを見ると、一度は指揮者になってみたいというのは、あながち僕だけの願望ではないらしい。","english":"Judging by how well virtual conducting software has been selling, apparently I''m not necessarily the only one who''d like to try orchestra conducting at least once in my life."}]'::jsonb),
    ('9357b6ee-2336-465f-a6e5-30fbf29654bc'::uuid,ARRAY['(i) Noun のあまり']::text[],ARRAY['Use this construction to express A conjunction which marks a cause that involves excessive action.. A conjunction which marks a cause that involves excessive action.']::text[],ARRAY['【Related Expression: 過ぎる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はその晩興奮のあまり寝られなかった。","japanese_furigana":"私はその晩興奮のあまり寝られなかった。","english":"I was so excited that I couldn''t sleep that night."},{"japanese":"この教科書は文法を重視するあまり面白くないものになってしまった。","japanese_furigana":"この教科書は文法を重視するあまり面白くないものになってしまった。","english":"This textbook has turned out to be an uninteresting one because it stressed grammar too much."}]'::jsonb),
    ('d163c4b9-b9c8-4325-a3c5-bc43fc0228c9'::uuid,ARRAY['お Vます する']::text[],ARRAY['Use this construction to express A phrase which humbly expresses the speaker’s politeness to someone when describing the speaker’s action or state that involves or affects that person.. A phrase which humbly expresses the speaker’s politeness to someone when describing the speaker’s action or state that involves or affects that person.']::text[],ARRAY['【Related Expression: お~になる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は先生のスーツケースをお持ちした・しました。","japanese_furigana":"私は先生のスーツケースをお持ちした・しました。","english":"I carried my teacher''s suitcase."},{"japanese":"そのことは私がお話ししましょう。","japanese_furigana":"そのことは私がお話ししましょう。","english":"I will tell you about that matter."}]'::jsonb),
    ('9a04404c-7b01-438b-8e17-4c347aef6a06'::uuid,ARRAY['(i) お Vます だ']::text[],ARRAY['Use this construction to express A phrase which expresses the speaker''s respect for someone when describing that person''s action or state.. A phrase which expresses the speaker''s respect for someone when describing that person''s action or state.']::text[],ARRAY['【Related Expression: お~になる; られる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"お急ぎですか。","japanese_furigana":"お急ぎですか。","english":"Are you in a hurry?"},{"japanese":"今お持ちのカードはもう使えません。","japanese_furigana":"今お持ちのカードはもう使えません。","english":"You can no longer use the card you have now."}]'::jsonb),
    ('1930045d-4ebd-47ca-a77b-ec8eb3007eec'::uuid,ARRAY['(i) お Vます 下さい']::text[],ARRAY['Use this construction to express A phrase which expresses a highly polite request.. A phrase which expresses a highly polite request.']::text[],ARRAY['【Related Expression: 下さい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"少々お待ち下さい。","japanese_furigana":"少々お待ち下さい。","english":"Please wait a moment."},{"japanese":"電話でご注文下さい。","japanese_furigana":"電話でご注文下さい。","english":"Please order by phone."}]'::jsonb),
    ('3ec11a5a-7a2f-4bb5-8cc6-3e764eacbe30'::uuid,ARRAY['(i) {V1/Adjective い1} informal か {V2/Adjective い2} informal か']::text[],ARRAY['Use this construction to express A structure to mark two choices or possibilities about which the speaker/writer is not sure.. A structure to mark two choices or possibilities about which the speaker/writer is not sure.']::text[],ARRAY['The core sense is A structure to mark two choices or possibilities about which the speaker/writer is not sure.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"来年日本へ行けるか行けないかまだ分かりません。","japanese_furigana":"来年日本へ行けるか行けないかまだ分かりません。","english":"I don''t know whether or not I can go to Japan next year."},{"japanese":"傘を駅に置き忘れたのか事務所に忘れたのか、はっきり覚えていません。","japanese_furigana":"傘を駅に置き忘れたのか事務所に忘れたのか、はっきり覚えていません。","english":"I don''t remember well whether I left my umbrella at the station or in my office."}]'::jsonb),
    ('a09036e5-bc82-427e-b982-a1763baba67a'::uuid,ARRAY['Noun 1 が Noun 2 なら ～ (だろう/かもしれない) WhereNoun 1 =Noun 2']::text[],ARRAY['Use this construction to express A structure presenting a counterfactual situation which indicates that things would be better if something were really good or appropriate.. A structure presenting a counterfactual situation which indicates that things would be better if something were really good or appropriate.']::text[],ARRAY['The core sense is A structure presenting a counterfactual situation which indicates that things would be better if something were really good or appropriate.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"会社が会社ならもう少しましな給料を出してくれるのだろうが。","japanese_furigana":"会社が会社ならもう少しましな給料を出してくれるのだろうが。","english":"If my company were a really good one, it would probably pay a bit better salary, but…"},{"japanese":"大学が大学ならもっといい教育が受けられて、いい就職もできたのだろう。","japanese_furigana":"大学が大学ならもっといい教育が受けられて、いい就職もできたのだろう。","english":"If the university had been a really good one, it would have given me a much better education, and I could have gotten a good job."}]'::jsonb),
    ('dae87882-6f27-4550-9f2d-3a9eced46d0b'::uuid,ARRAY['(i) {Verb/Adjective い} か']::text[],ARRAY['Use this construction to express A sentence final particle which indicates that the preceding sentence is interrogative.. A sentence final particle which indicates that the preceding sentence is interrogative.']::text[],ARRAY['【Related Expression: だい (かい)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"よし子は大学へ行く・行きますか。","japanese_furigana":"よし子は大学へ行く・行きますか。","english":"Is Yoshiko going to college?"},{"japanese":"私はテリーにナンシが日本へ行くかと聞いた・聞きました。","japanese_furigana":"私はテリーにナンシが日本へ行くかと聞いた・聞きました。","english":"I asked Terry whether Nancy was going to Japan."}]'::jsonb),
    ('da99d151-1442-4103-96cd-9e48b94bc92d'::uuid,ARRAY['S1 が S2 太郎は泳いだ が 次郎は泳がなかった。 Taro swam but Jiro didn''t swim.']::text[],ARRAY['Use this construction to express A disjunctive coordinate conjunction that combines two sentences.. A disjunctive coordinate conjunction that combines two sentences.']::text[],ARRAY['【Related Expression: だが; だけど; でも; けれども; しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ジョンは来た・来ましたがメアリーは来なかった・来ませんでした。","japanese_furigana":"ジョンは来た・来ましたがメアリーは来なかった・来ませんでした。","english":"John came but Mary didn''t (come)."},{"japanese":"私はビールは飲むが酒は飲まない。","japanese_furigana":"私はビールは飲むが酒は飲まない。","english":"I drink beer but don''t drink sake."}]'::jsonb),
    ('4b0875d7-6c8e-449e-90e2-4df4606f5bc0'::uuid,ARRAY['(i) {V/Adjective い} informal か']::text[],ARRAY['Use this construction to express A particle which marks an alternative.. A particle which marks an alternative.']::text[],ARRAY['【Related Expression: それとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は電車かバス（か）で行く・行きます。","japanese_furigana":"私は電車かバス（か）で行く・行きます。","english":"I will go either by train or by bus."},{"japanese":"トムが行くかメアリーが行くかどちらかだ・です。","japanese_furigana":"トムが行くかメアリーが行くかどちらかだ・です。","english":"Either Tom will go or Mary will go."}]'::jsonb),
    ('e225bdf5-9c0d-469a-b5e5-3e59b051b3b5'::uuid,ARRAY['(i) {V/Adjective い informal} かい']::text[],ARRAY['Use this construction to express A sentence final particle which marks yes-no questions in informal male speech.. A sentence final particle which marks yes-no questions in informal male speech.']::text[],ARRAY['【Related Expression: だい (か2)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語は面白いかい。","japanese_furigana":"日本語は面白いかい。","english":"Is Japanese interesting?"},{"japanese":"上野さんはアメリカへ行くのかい。","japanese_furigana":"上野さんはアメリカへ行くのかい。","english":"Is Mr. Ueno going to America?"}]'::jsonb),
    ('96b96438-0402-49b5-aeda-fd62fb82e99d'::uuid,ARRAY['(i) {V/Adjective い} informal かしら']::text[],ARRAY['Use this construction to express A sentence final particle which expresses the idea that the female speaker wonders about something.. A sentence final particle which expresses the idea that the female speaker wonders about something.']::text[],ARRAY['The core sense is A sentence final particle which expresses the idea that the female speaker wonders about something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"松本さんは来るかしら。","japanese_furigana":"松本さんは来るかしら。","english":"I wonder if Mr. Matsumoto will come."},{"japanese":"あの先生の授業は面白いかしら。","japanese_furigana":"あの先生の授業は面白いかしら。","english":"I wonder if that teacher''s class is interesting."}]'::jsonb),
    ('62cee8db-44a0-49b5-a680-a1ede1a4f697'::uuid,ARRAY['Canonical pattern: 〜がする（感覚）']::text[],ARRAY['Use this construction to express Something is perceived by someone’s non-visual senses.. Something is perceived by someone’s non-visual senses.']::text[],ARRAY['The core sense is Something is perceived by someone’s non-visual senses.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"子供達の声がした・しました。","japanese_furigana":"子供達の声がした・しました。","english":"I heard children''s voices."},{"japanese":"この魚は変な味がしますね。","japanese_furigana":"この魚は変な味がしますね。","english":"This fish tastes funny, doesn''t it?"}]'::jsonb),
    ('c6f9a075-0dce-42b7-b7e5-6d7cf217d99f'::uuid,ARRAY['Vます がたい']::text[],ARRAY['Use this construction to express An auxiliary adjective which expresses the idea that for someone to do something is virtually impossible or impossible.. An auxiliary adjective which expresses the idea that for someone to do something is virtually impossible or impossible.']::text[],ARRAY['【Related Expression: かねる; 難い; づらい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼のしたことは許しがたい。","japanese_furigana":"彼のしたことは許しがたい。","english":"What he did is unforgivable."},{"japanese":"この旅行は私にとって忘れがたい思い出になるだろう。","japanese_furigana":"この旅行は私にとって忘れがたい思い出になるだろう。","english":"This trip will be an unforgettable one (literally: memory) for me."}]'::jsonb),
    ('c7e0f224-c91f-40b0-a9f7-a7f26da236a0'::uuid,ARRAY['(i) Vます がちだ']::text[],ARRAY['Use this construction to express A suffix to express an undesirable tendency in someone or something.. A suffix to express an undesirable tendency in someone or something.']::text[],ARRAY['【Related Expression: ぎみ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"田中君は最近授業を休みがちだ。","japanese_furigana":"田中君は最近授業を休みがちだ。","english":"Tanaka tends to miss classes these days."},{"japanese":"それは日本に短期間滞在した外国人にありがちな誤解だ。","japanese_furigana":"それは日本に短期間滞在した外国人にありがちな誤解だ。","english":"That''s the kind of misunderstanding which foreigners who stay in Japan for a short period of time are subject to."}]'::jsonb),
    ('cf2f3eb6-fd8d-4548-95a7-cec90bd5acf4'::uuid,ARRAY['(i) Sentence1 informal past かと思うと 、Sentence2 Where the predicate in Sentence2 is non-emotive; the subjects in Sentence1 and Sentence2 are the same']::text[],ARRAY['Use this construction to express A phrase indicating that an action or state in the dependent clause occurs very closely with another action or state in the clause, or causes another action or state in the main clause.. A phrase indicating that an action or state in the dependent clause occurs very closely with another action or state in the clause, or causes another action or state in the main clause.']::text[],ARRAY['【Related Expression: かと思えば; かと思ったら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"最近は、肌寒くなったかと思うと、翌日には暖かくなったりする。","japanese_furigana":"最近は、肌寒くなったかと思うと、翌日には暖かくなったりする。","english":"These days, just when you think it''s gotten chilly, the next day it turns warm again."},{"japanese":"私の書いた小説が出版されるかと思うと、とても嬉しい。","japanese_furigana":"私の書いた小説が出版されるかと思うと、とても嬉しい。","english":"When I think that the novel I wrote will be published, I feel very happy."}]'::jsonb),
    ('ce11ce62-1ae1-4f36-a74e-adb475b698df'::uuid,ARRAY['(i) {V/Vvolitional} informal かな']::text[],ARRAY['Use this construction to express A sentence-final particle that indicates a self-addressed question or a question addressed to an in-group member.. A sentence-final particle that indicates a self-addressed question or a question addressed to an in-group member.']::text[],ARRAY['The core sense is A sentence-final particle that indicates a self-addressed question or a question addressed to an in-group member.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"今週末には何をしようかな。","japanese_furigana":"今週末には何をしようかな。","english":"I wonder what I should do this weekend."},{"japanese":"この問題、君に分かるかな。","japanese_furigana":"この問題、君に分かるかな。","english":"Can you figure out this problem?"}]'::jsonb),
    ('4ae8571c-1f2b-4bb6-b3c0-804d96c8b0d3'::uuid,ARRAY['Vます かねる / かねない']::text[],ARRAY['Use this construction to express An auxiliary expressing that someone cannot do something even if s/he wants to do it.. An auxiliary expressing that someone cannot do something even if s/he wants to do it.']::text[],ARRAY['【Related Expression: がたい; 難い】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"そのことは私には分かりかねますから、部長にお聞きになって下さい。","japanese_furigana":"そのことは私には分かりかねますから、部長にお聞きになって下さい。","english":"I am not in a position to figure out that matter, so please ask the departmental chief."},{"japanese":"あの男はどんな馬鹿なことでもやりかねない。","japanese_furigana":"あの男はどんな馬鹿なことでもやりかねない。","english":"He might (literally: can) do any stupid thing."}]'::jsonb),
    ('60ccb91d-b0b9-4834-8fb4-33e571c38287'::uuid,ARRAY['(i) {まるで/あたかも} {V/Adjective い}informal かのように']::text[],ARRAY['Use this construction to express A conjunctive phrase that forms an adverbial clause which describes the way someone/something appears to the writer, contrary to reality.. A conjunctive phrase that forms an adverbial clause which describes the way someone/something appears to the writer, contrary to reality.']::text[],ARRAY['【Related Expression: かの如く; あたかも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は(まるで)整形手術したかのようにきれいになった。","japanese_furigana":"彼女は(まるで)整形手術したかのようにきれいになった。","english":"Her looks improved (literally: She became beautiful), as though she had undergone cosmetic surgery."},{"japanese":"彼女の病気は年内に治るかのように見えた。","japanese_furigana":"彼女の病気は年内に治るかのように見えた。","english":"It looked as though her illness would be cured before the end of the year."}]'::jsonb),
    ('53964837-dfba-4bf8-a5d1-a22280136f40'::uuid,ARRAY['Noun から Noun にかけて']::text[],ARRAY['Use this construction to express A structure that expresses coverage from one time/location into the other.. A structure that expresses coverage from one time/location into the other.']::text[],ARRAY['【Related Expression: から~まで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の夏、七月から八月にかけて中国大陸を旅行した。","japanese_furigana":"今年の夏、七月から八月にかけて中国大陸を旅行した。","english":"This summer I travelled on the Chinese continent from July through August."},{"japanese":"今週は木曜から金曜にかけて雪が降るでしょう。","japanese_furigana":"今週は木曜から金曜にかけて雪が降るでしょう。","english":"This week it will probably snow from Thursday through Friday."}]'::jsonb),
    ('d8c1770b-646b-4ecc-a3e9-10d9a09d3987'::uuid,ARRAY['Canonical pattern: 〜から〜に至るまで']::text[],ARRAY['Use this construction to express A structure that expresses a wide range of things.. A structure that expresses a wide range of things.']::text[],ARRAY['【Related Expression: から~まで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミスさんは週刊誌から学術書に至るまで、幅広い日本語が読める。","japanese_furigana":"スミスさんは週刊誌から学術書に至るまで、幅広い日本語が読める。","english":"Mr. Smith can read Japanese widely, ranging from weekly magazines to scholastic books."},{"japanese":"その新聞記者は首相の公の生活から私生活に至るまで、何でも知っている。","japanese_furigana":"その新聞記者は首相の公の生活から私生活に至るまで、何でも知っている。","english":"That newspaper reporter knows everything about the premier, ranging from his public life to his private life."}]'::jsonb),
    ('a8462484-a9a2-48e9-8e9c-c71ca6c069bd'::uuid,ARRAY['Vてから 話して から After talking']::text[],ARRAY['Use this construction to express After/since a point in time at which something takes place.. After/since a point in time at which something takes place.']::text[],ARRAY['【Related Expression: あとで; てform of verb】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"雪子は晩ご飯を食べてから映画に行った・行きました。","japanese_furigana":"雪子は晩ご飯を食べてから映画に行った・行きました。","english":"After eating her supper, Yukiko went to a movie."},{"japanese":"私は友達に電話してからうちを出た。","japanese_furigana":"私は友達に電話してからうちを出た。","english":"I left home after making a call to my friend."}]'::jsonb),
    ('75766188-918b-417e-877c-7e5480b40b50'::uuid,ARRAY['Canonical pattern: 〜から（起点・出所）']::text[],ARRAY['Use this construction to express A particle which indicates a starting point or a source.. A particle which indicates a starting point or a source.']::text[],ARRAY['【Related Expression: に3; を3】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"パーティーは八時から始まる・始まります。","japanese_furigana":"パーティーは八時から始まる・始まります。","english":"The party starts from eight o''clock."},{"japanese":"今日の授業は一時から三時までです。","japanese_furigana":"今日の授業は一時から三時までです。","english":"Today''s class is from one o''clock till three o''clock."}]'::jsonb),
    ('8787e77e-286a-4f1f-9b92-fc0e5c239501'::uuid,ARRAY['Noun からして']::text[],ARRAY['Use this construction to express A phrase that singles out something for emphasis or presents something as a basis for judgment.. A phrase that singles out something for emphasis or presents something as a basis for judgment.']::text[],ARRAY['【Related Expression: (で)すら; (で)さえ; からいって; からみて; にしてからが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"社長からして会社再建の意欲がないんだから、社員の志気が上がらないのは当たり前だ。","japanese_furigana":"社長からして会社再建の意欲がないんだから、社員の志気が上がらないのは当たり前だ。","english":"Even the president has no desire to reconstruct the company; so, of course, his employees'' morale is low."},{"japanese":"あの日本語の話し方からして彼は日本に行ったことがあるに違いない。","japanese_furigana":"あの日本語の話し方からして彼は日本に行ったことがあるに違いない。","english":"Judging from the way he speaks Japanese, he must have been to Japan."}]'::jsonb),
    ('a6bb0848-5d8c-409a-864d-fe3203c62c62'::uuid,ARRAY['(i) (Xは) Noun 1 とNoun 2 (と…)(と) から { なる / なっている }']::text[],ARRAY['Use this construction to express A phrase indicating that something consists of more than one member/constituent.. A phrase indicating that something consists of more than one member/constituent.']::text[],ARRAY['The core sense is A phrase indicating that something consists of more than one member/constituent.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"英語の”relax”はラテン語の”re-”(再び)と”laxare”（緩む）とからなっている。","japanese_furigana":"英語の”relax”はラテン語の”re-”(再び)と”laxare”（緩む）とからなっている。","english":"The English word “relax” consists of the Latin “re-” (again) and “laxare” (to loosen)."},{"japanese":"タンパク質はアミノ酸からなっている。","japanese_furigana":"タンパク質はアミノ酸からなっている。","english":"Proteins are composed of amino acids."}]'::jsonb),
    ('c8aa9292-f124-47d9-9846-6436d040ab7f'::uuid,ARRAY['(i) Vinformal からには']::text[],ARRAY['Use this construction to express A subordinate conjunction meaning “now that,” “once someone does / has done something” or “so long as”.. A subordinate conjunction meaning “now that,” “once someone does / has done something” or “so long as”.']::text[],ARRAY['【Related Expression: 以上(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"いったん引き受けたからには最後まで責任をもってやります。","japanese_furigana":"いったん引き受けたからには最後まで責任をもってやります。","english":"Once I take on (the job), I will fulﬁll my responsibility and complete it."},{"japanese":"裁判と言うからには弁護人が不可欠だ。","japanese_furigana":"裁判と言うからには弁護人が不可欠だ。","english":"Since it is a trial, a defence attorney will be indispensable."}]'::jsonb),
    ('4da19598-04e6-430c-b9a7-014ddc3ffb8a'::uuid,ARRAY['Noun から言って']::text[],ARRAY['Use this construction to express A phrase that means either “in terms of” or “judging from”.. A phrase that means either “in terms of” or “judging from”.']::text[],ARRAY['【Related Expression: の点で; からして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"燃費から言ってこの車は非常に経済的だ。","japanese_furigana":"燃費から言ってこの車は非常に経済的だ。","english":"In terms of gas mileage, this car is extremely economical."},{"japanese":"学生の評価から言って鈴木先生はいい先生に違いない。","japanese_furigana":"学生の評価から言って鈴木先生はいい先生に違いない。","english":"Judging from his student evaluations, Professor Suzuki must be a fine teacher."}]'::jsonb),
    ('1a7b538b-357f-4043-8d7c-1774234fbe7b'::uuid,ARRAY['(i) Adjective い stem かろう']::text[],ARRAY['Use this construction to express An auxiliary indicating the writer''s conjecture which is not based on any particular information or evidence.. An auxiliary indicating the writer''s conjecture which is not based on any particular information or evidence.']::text[],ARRAY['【Related Expression: だろう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"十年後の自分を予想するのは難しかろう。","japanese_furigana":"十年後の自分を予想するのは難しかろう。","english":"It is probably difficult to predict what one''s self will be like in ten years time."},{"japanese":"この研究を一年で完成するのは極めて難しかろう。","japanese_furigana":"この研究を一年で完成するのは極めて難しかろう。","english":"It is probably extremely difficult to complete this research in one year."}]'::jsonb),
    ('d9b04553-557b-4116-bf8f-61f9d673aeef'::uuid,ARRAY['(i) {V/Adjectiveい} informal か否か']::text[],ARRAY['Use this construction to express A conjunctive phrase indicating that the speaker/writer is wondering whether something is the case or not.. A conjunctive phrase indicating that the speaker/writer is wondering whether something is the case or not.']::text[],ARRAY['【Related Expression: か~ないか; かどうか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このソフトが役に立つか否かは保証の限りではありません。","japanese_furigana":"このソフトが役に立つか否かは保証の限りではありません。","english":"I cannot say (literally: guarantee) whether this software is useful or not."},{"japanese":"選挙の時に、有権者は候補者が倫理観のある政治家（である）か否かを見抜かなければならない。","japanese_furigana":"選挙の時に、有権者は候補者が倫理観のある政治家（である）か否かを見抜かなければならない。","english":"In an election, the voter has to judge (literally: see through) whether or not a candidate is a politician of integrity."}]'::jsonb),
    ('b39fb22d-8c1c-4d1a-80a8-e9eed6678edb'::uuid,ARRAY['(i) Vinformal きらいがある']::text[],ARRAY['Use this construction to express A phrase indicating that someone or something has an undesirable tendency.. A phrase indicating that someone or something has an undesirable tendency.']::text[],ARRAY['【Related Expression: がち; 傾向がある】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は物事を単純に考えるきらいがある。","japanese_furigana":"彼は物事を単純に考えるきらいがある。","english":"He has a tendency to think (about things) in simplistic terms."},{"japanese":"彼は独断のきらいがある。","japanese_furigana":"彼は独断のきらいがある。","english":"He is slightly dogmatic (literally: has a touch of dogmatism)."}]'::jsonb),
    ('ac9700a1-2634-4374-8873-14f2e74c7dd0'::uuid,ARRAY['Canonical pattern: 〜くする／〜にする（変化）']::text[],ARRAY['Use this construction to express Someone/something causes a state or action to take place.. Someone/something causes a state or action to take place.']::text[],ARRAY['【Related Expression: なる; やる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"中山さんはテニスをする・します。","japanese_furigana":"中山さんはテニスをする・します。","english":"Mr. Nakayama plays tennis."},{"japanese":"リーズさんは英語の先生をしている・います。","japanese_furigana":"リーズさんは英語の先生をしている・います。","english":"Mr. Leeds is an English teacher."}]'::jsonb),
    ('5bd04a1b-992a-42ba-875c-973c54116710'::uuid,ARRAY['(i) Noun (particle) こそ']::text[],ARRAY['Use this construction to express A particle which emphasizes a word, phrase, or clause.. A particle which emphasizes a word, phrase, or clause.']::text[],ARRAY['The core sense is A particle which emphasizes a word, phrase, or clause.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"これこそ我々が探し求めていたものだ。","japanese_furigana":"これこそ我々が探し求めていたものだ。","english":"This is the very thing that we''ve been looking for."},{"japanese":"Ａ：どうもすみませんでした。 Ｂ：いいえ、こちらこそすみませんでした。","japanese_furigana":"Ａ：どうもすみませんでした。 Ｂ：いいえ、こちらこそすみませんでした。","english":"A: I''m very sorry. B: No, it''s me who should say that (literally: be sorry)."}]'::jsonb),
    ('8e3d66d6-d71a-4055-8a0c-afec9eb09e95'::uuid,ARRAY['(i) Vinformal nonpast Affirmative/negative こと']::text[],ARRAY['Use this construction to express An auxiliary noun to express a command.. An auxiliary noun to express a command.']::text[],ARRAY['【Related Expression: Imperative】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"発表は十五分以内で行うこと。","japanese_furigana":"発表は十五分以内で行うこと。","english":"Each presentation should be completed (literally: done) within fifteen minutes."},{"japanese":"プールサイドを走らないこと。","japanese_furigana":"プールサイドを走らないこと。","english":"Do not run on the pool deck."}]'::jsonb),
    ('a9fe5ca8-53ff-4c8a-84a1-3523f5f99236'::uuid,ARRAY['(i) V/Adjective い informal nonpast ことがある']::text[],ARRAY['Use this construction to express There are times when ~.. There are times when ~.']::text[],ARRAY['The core sense is There are times when ~.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は朝風呂に入ることがある・あります。","japanese_furigana":"私は朝風呂に入ることがある・あります。","english":"There are times when I take a bath in the morning."},{"japanese":"たかしは朝ご飯を食べずに学校へ行くことがある。","japanese_furigana":"たかしは朝ご飯を食べずに学校へ行くことがある。","english":"There are times when Takashi goes to school without eating breakfast."}]'::jsonb),
    ('dfba262e-3f54-4258-9962-617886f902c7'::uuid,ARRAY['(i) {V/Adjectiveい}informal ことから']::text[],ARRAY['Use this construction to express A phrase that expresses a reason or a cause.. A phrase that expresses a reason or a cause.']::text[],ARRAY['【Related Expression: から; ので; ところから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はアリバイが成立しなかったことから犯行の嫌疑がかかった。","japanese_furigana":"彼はアリバイが成立しなかったことから犯行の嫌疑がかかった。","english":"Because (literally: from the fact that) he couldn''t establish an alibi, he was suspected of a criminal act."},{"japanese":"妙なことから二人の関係は悪化した。","japanese_furigana":"妙なことから二人の関係は悪化した。","english":"The relationship between the two people deteriorated due to strange circumstances."}]'::jsonb),
    ('afa0634b-45b7-413a-ade8-af59470ee975'::uuid,ARRAY['(i) Nounの ごとし']::text[],ARRAY['Use this construction to express An auxiliary adjective that indicates a resemblance of something/someone to something/someone or indicates how something/someone appears to speaker/writer.. An auxiliary adjective that indicates a resemblance of something/someone to something/someone or indicates how something/someone appears to speaker/writer.']::text[],ARRAY['【Related Expression: ようだ; みたいだ; かのように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"人生は旅のごとし。","japanese_furigana":"人生は旅のごとし。","english":"Life is like a journey."},{"japanese":"その無謀な行為は火中に飛び込む｛が/かの｝ごとし。","japanese_furigana":"その無謀な行為は火中に飛び込む｛が/かの｝ごとし。","english":"Acting recklessly like that is like jumping into the ﬁre."}]'::jsonb),
    ('629bc104-b1de-495f-b44a-79224a59b649'::uuid,ARRAY['(i) Vinformal nonpast ことで Means']::text[],ARRAY['Use this construction to express A compound particle which indicates a means or a cause.. A compound particle which indicates a means or a cause.']::text[],ARRAY['【Related Expression: から; ことにより; よって; ので; 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は週末にゴルフをすることで気分転換を図っています。","japanese_furigana":"私は週末にゴルフをすることで気分転換を図っています。","english":"I try to lift my spirits by playing golf on weekends."},{"japanese":"彼が仲裁の場に出ていったことで事態は余計にこじれた。","japanese_furigana":"彼が仲裁の場に出ていったことで事態は余計にこじれた。","english":"His appearance at the mediation scene complicated the situation even more. (literally: The situation got even more complicated because he appeared at the mediation scene.)"}]'::jsonb),
    ('e079ae47-e27e-4d5d-aed4-ebf207313b74'::uuid,ARRAY['(i) Adjectiveいinformal ことに']::text[],ARRAY['Use this construction to express A phrase that expresses the speaker’s/ writer’s emotion or subjective judgment.. A phrase that expresses the speaker’s/ writer’s emotion or subjective judgment.']::text[],ARRAY['【Related Expression: とは; にも; かな】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"嬉しいことに、今学期は祭日が3日もある。","japanese_furigana":"嬉しいことに、今学期は祭日が3日もある。","english":"I''m glad that there are (as many as) three holidays this term."},{"japanese":"残念なことに、この本は絶版で、普通の本屋では手に入らない。","japanese_furigana":"残念なことに、この本は絶版で、普通の本屋では手に入らない。","english":"To my regret, this book is out of print and cannot be purchased at ordinary bookstores."}]'::jsonb),
    ('837e0548-5f40-4bab-bb33-228bd9c05cd7'::uuid,ARRAY['Sinformal ことによる Exceptions: Adjective な stem なことによる; Noun であることによる']::text[],ARRAY['Use this construction to express A phrase which is used to present an event as the cause of something.. A phrase which is used to present an event as the cause of something.']::text[],ARRAY['【Related Expression: からだ; ためだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今回の失敗は事前の話し合いが不十分だったことによる。","japanese_furigana":"今回の失敗は事前の話し合いが不十分だったことによる。","english":"The failure this time is the result of insufficient discussion beforehand (literally: due to the fact that the preceding discussion was insufficient)."},{"japanese":"進が非行に走ったの両親の愛情が不足していたことによる。","japanese_furigana":"進が非行に走ったの両親の愛情が不足していたことによる。","english":"Susumu''s delinquency was caused by his parents'' lack of affection. (literally: The fact that Susumu ran to juvenile delinquency is because his parents were not affectionate enough with him."}]'::jsonb),
    ('86cb8976-5cc5-4723-b66a-be5d796994f6'::uuid,ARRAY['Vinformal nonpast ことはない Affirmation']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that there is no need to do something or that there is no possibility of doing something.. A phrase which expresses the idea that there is no need to do something or that there is no possibility of doing something.']::text[],ARRAY['【Related Expression: はずはない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あんな男の言うことを聞くことはない。","japanese_furigana":"あんな男の言うことを聞くことはない。","english":"There''s no need to listen to a man like that."},{"japanese":"彼女が今日の会議を忘れることはないと思います。","japanese_furigana":"彼女が今日の会議を忘れることはないと思います。","english":"I think that there is no possibility that she will forget today''s meeting."}]'::jsonb),
    ('c7d29740-b01a-4ffc-987b-6d49e840fa4d'::uuid,ARRAY['(i) Adjective な stem この上ない']::text[],ARRAY['Use this construction to express A phrase that indicates that something or someone is in an extreme state.. A phrase that indicates that something or someone is in an extreme state.']::text[],ARRAY['【Related Expression: 極めて; 非常に; 実に; 極まりない; 限りだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"生まれたばかりの赤ん坊を車に残して買い物に行くとは非常識この上ない。","japanese_furigana":"生まれたばかりの赤ん坊を車に残して買い物に行くとは非常識この上ない。","english":"It is utterly senseless to leave a newborn baby in the car and go shopping."},{"japanese":"この部屋はクーラーも扇風機もなく、風も全然通らないので、暑いことこの上ない。","japanese_furigana":"この部屋はクーラーも扇風機もなく、風も全然通らないので、暑いことこの上ない。","english":"There is neither an air-conditioner nor a fan in this room, and no breeze, either, so it''s extremely hot in here."}]'::jsonb),
    ('bafff5c6-be8c-48bd-92da-94330711e807'::uuid,ARRAY['Adjective (い/な) stem さ']::text[],ARRAY['Use this construction to express A suffix that makes a noun out of an adjective by attaching it to the stem of an Adj (い) or much less frequently to the stem of an Adj (な). A suffix that makes a noun out of an adjective by attaching it to the stem of an Adj (い) or much less frequently to the stem of an Adj (な)']::text[],ARRAY['【Related Expression: み】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このうちの広さはちょうどいい・いいです。","japanese_furigana":"このうちの広さはちょうどいい・いいです。","english":"This size of this house is just right."},{"japanese":"富士山の高さはどのぐらいですか。","japanese_furigana":"富士山の高さはどのぐらいですか。","english":"What is the approximate height of Mt. Fuji?"}]'::jsonb),
    ('eb32afae-6b6b-4ac5-a5fa-32e00d0f6740'::uuid,ARRAY['(i) {V/Adjective い}informal さ']::text[],ARRAY['Use this construction to express A sentence final particle used in highly informal speech by male speakers to express different degrees of assertion ranging from a light touch comment up to opposition or imposition.. A sentence final particle used in highly informal speech by male speakers to express different degrees of assertion ranging from a light touch comment up to opposition or imposition.']::text[],ARRAY['【Related Expression: ね; とも; よ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：就職出来るかな。Ｂ：出来るさ。","japanese_furigana":"Ａ：就職出来るかな。Ｂ：出来るさ。","english":"A: I wonder if I can get a job. B: Sure you can."},{"japanese":"Ａ：君は日本語、読めないよね。Ｂ：いや、読めるさ。","japanese_furigana":"Ａ：君は日本語、読めないよね。Ｂ：いや、読めるさ。","english":"A: You cannot read Japanese, right? B: Yeah, sure I can."}]'::jsonb),
    ('a35eb2e9-13fa-4423-80db-e9797fa36475'::uuid,ARRAY['Vneg ざるを得ない']::text[],ARRAY['Use this construction to express An auxiliary indicating that there is no other choice but to do something.. An auxiliary indicating that there is no other choice but to do something.']::text[],ARRAY['【Related Expression: ないわけに(は)いかない; なければならない; しかない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"それは高かったが、教科書だったから買わざるを得なかった。","japanese_furigana":"それは高かったが、教科書だったから買わざるを得なかった。","english":"It was a textbook so I had no choice but to buy it, although it was expensive."},{"japanese":"日本へ行けば、日本の習慣に従わざるを得ない。","japanese_furigana":"日本へ行けば、日本の習慣に従わざるを得ない。","english":"If you go to Japan you cannot help but adapt yourself to Japanese customs."}]'::jsonb),
    ('9ce6068a-0a08-4156-91d6-1bbe8b2e51cc'::uuid,ARRAY['(i) Noun しか']::text[],ARRAY['Use this construction to express A particle which marks an element X when nothing but X makes the expressed proposition true.. A particle which marks an element X when nothing but X makes the expressed proposition true.']::text[],ARRAY['【Related Expression: ばかり; だけ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"戸田さんしか煙草を吸わない・吸いません。","japanese_furigana":"戸田さんしか煙草を吸わない・吸いません。","english":"No one but Mr. Toda smokes."},{"japanese":"私は日本語しか知らない・知りません。","japanese_furigana":"私は日本語しか知らない・知りません。","english":"I know nothing but Japanese."}]'::jsonb),
    ('0d4b02d0-a5e5-4f3b-9d8a-724778b1208e'::uuid,ARRAY['Vて しまう']::text[],ARRAY['Use this construction to express An auxiliary verb which indicates the completion of an action.. An auxiliary verb which indicates the completion of an action.']::text[],ARRAY['【Related Expression:~終わる 】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"池田君は三日でその本を読んでしまった・しまいました。","japanese_furigana":"池田君は三日でその本を読んでしまった・しまいました。","english":"Mr. Ikeda finished reading the book in three days."},{"japanese":"私はルームメートのミルクを飲んでしまった・しまいました。","japanese_furigana":"私はルームメートのミルクを飲んでしまった・しまいました。","english":"I (mistakenly) drank my roommate''s milk."}]'::jsonb),
    ('a7a390c9-1dac-4353-a2d7-07ffba181f6e'::uuid,ARRAY['Vnegative ずして Exception: する→せずして']::text[],ARRAY['Use this construction to express A phrase meaning “without doing something”.. A phrase meaning “without doing something”.']::text[],ARRAY['【Related Expression: ずに; ないで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インカ帝国を知らずして南米大陸を語ることはできない。","japanese_furigana":"インカ帝国を知らずして南米大陸を語ることはできない。","english":"You cannot talk about the South American continent without some knowledge of the Inca Empire."},{"japanese":"我々のチームは最終日の最終戦を待たずして優勝が決定した。","japanese_furigana":"我々のチームは最終日の最終戦を待たずして優勝が決定した。","english":"Our team won the championship before (literally: without waiting for) the ﬁnal game on the ﬁnal day."}]'::jsonb),
    ('4f1d5fc0-f8ce-4da4-b5a0-a1b7a3619907'::uuid,ARRAY['Canonical pattern: 〜ずつ']::text[],ARRAY['Use this construction to express A particle that indicates equal distribution of quantity.. A particle that indicates equal distribution of quantity.']::text[],ARRAY['The core sense is A particle that indicates equal distribution of quantity.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は漢字を毎日五つずつ覚える・覚えます。","japanese_furigana":"私は漢字を毎日五つずつ覚える・覚えます。","english":"I memorize five kanji every day."},{"japanese":"毎月三冊ずつ本を買っています。","japanese_furigana":"毎月三冊ずつ本を買っています。","english":"I''m buying three books per month."}]'::jsonb),
    ('081402d0-4fc3-42af-b2b6-cf605438bd5d'::uuid,ARRAY['(i) Vnegative ずとも Exception: する→せずとも']::text[],ARRAY['Use this construction to express A conjunctive phrase that indicates negative concession: “even if ~ not”.. A conjunctive phrase that indicates negative concession: “even if ~ not”.']::text[],ARRAY['【Related Expression: なくても; ないでも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の夏は涼しいので、エアコンを使わずとも過ごせそうだ。","japanese_furigana":"今年の夏は涼しいので、エアコンを使わずとも過ごせそうだ。","english":"It is cool this summer, so it looks like we can get by without using the air-conditioner."},{"japanese":"シカゴには親しい友人が何人かいるので、ホテルに泊まらずともよい。","japanese_furigana":"シカゴには親しい友人が何人かいるので、ホテルに泊まらずともよい。","english":"Because I have several close friends in Chicago, I don''t have to stay at a hotel."}]'::jsonb),
    ('626a3076-4715-4f2d-8751-c9ae557b5e6c'::uuid,ARRAY['Vnegative ずにはおかない Exception: する→せずにはおかない']::text[],ARRAY['Use this construction to express A phrase that expresses the idea that someone/something necessarily or naturally causes something to happen.. A phrase that expresses the idea that someone/something necessarily or naturally causes something to happen.']::text[],ARRAY['【Related Expression: 必ず; 間違いなく; 絶対に; ずにはおられない/おれない/いられない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"技術の発達は社会環境の変化をもたらさずにはおかない。","japanese_furigana":"技術の発達は社会環境の変化をもたらさずにはおかない。","english":"Technological advancements are bound to bring about changes to social environments."},{"japanese":"コンピュータの普及とインターネット利用の拡大は大きな教育の変革を促さずにはおかない。","japanese_furigana":"コンピュータの普及とインターネット利用の拡大は大きな教育の変革を促さずにはおかない。","english":"The spread of computers and the expansion of Internet use are bound to promote big changes in education."}]'::jsonb),
    ('9ca85fa3-73af-40e8-9b25-f4ff054c79bd'::uuid,ARRAY['{V/Adjective い} informal ぞ']::text[],ARRAY['Use this construction to express A sentence final particle that emphasises a male speaker''s emotion about something in his monologue or his strong desire to draw someone else''s attention.. A sentence final particle that emphasises a male speaker''s emotion about something in his monologue or his strong desire to draw someone else''s attention.']::text[],ARRAY['【Related Expression: よ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あれ、財布がどこかへ行ってしまったぞ。","japanese_furigana":"あれ、財布がどこかへ行ってしまったぞ。","english":"Hey, my purse has gone somewhere!"},{"japanese":"急がないとバスに乗り遅れるぞ。","japanese_furigana":"急がないとバスに乗り遅れるぞ。","english":"If you don''t hurry, you''ll be late for the bus, you know."}]'::jsonb),
    ('7b57533c-6399-4457-b9d7-db0f2da13b71'::uuid,ARRAY['(i) A: Sentence1']::text[],ARRAY['Use this construction to express A structure which expresses that the speaker/writer cannot easily accept the corollary from the preceding statement owing to some circumstances, although he feels like accepting it. A structure which expresses that the speaker/writer cannot easily accept the corollary from the preceding statement owing to some circumstances, although he feels like accepting it']::text[],ARRAY['【Related Expression: (そう)ですが; けれど(も); しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：魚が体にいいそうですよ。Ｂ：そうかと言って、毎日魚ばかりを食べているわけにもいかないでしょう。","japanese_furigana":"Ａ：魚が体にいいそうですよ。Ｂ：そうかと言って、毎日魚ばかりを食べているわけにもいかないでしょう。","english":"A: I hear that fish is good for your health. B: But we couldn''t eat just fish every day, you know."},{"japanese":"アメリカの方が土地も家も安いが、そうかと言って、簡単に移住するわけにもいかない。","japanese_furigana":"アメリカの方が土地も家も安いが、そうかと言って、簡単に移住するわけにもいかない。","english":"Land and housing are less expensive in America, but we cannot easily immigrate."}]'::jsonb),
    ('cbeb6c0c-0215-406a-99bf-e1da1279b4bb'::uuid,ARRAY['Vます そうになる']::text[],ARRAY['Use this construction to express A phrase expressing that something almost happens.. A phrase expressing that something almost happens.']::text[],ARRAY['【Related Expression: もう少し; ちょっとで~するところ(だった)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"冷たい雨の中を傘もささないで歩いていたら、風邪を引きそうになった。","japanese_furigana":"冷たい雨の中を傘もささないで歩いていたら、風邪を引きそうになった。","english":"While walking in the cold rain without using an umbrella, I almost caught a cold."},{"japanese":"私は子供の時、プールで危うく溺れそうになったことがある。","japanese_furigana":"私は子供の時、プールで危うく溺れそうになったことがある。","english":"When I was a child I almost drowned in a swimming pool."}]'::jsonb),
    ('3fb4ca26-f9f4-4433-84cd-6818d7adade3'::uuid,ARRAY['(i) Noun そのもの']::text[],ARRAY['Use this construction to express A phrase used to refer strictly to the preceding noun (phrase) or adjective.. A phrase used to refer strictly to the preceding noun (phrase) or adjective.']::text[],ARRAY['【Related Expression: 自体; 自身】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"マイナス思考ばかりしていると、人生そのものが駄目になる。","japanese_furigana":"マイナス思考ばかりしていると、人生そのものが駄目になる。","english":"If you remain a negative thinker, your life itself will be ruined."},{"japanese":"企画そのものは悪くない。","japanese_furigana":"企画そのものは悪くない。","english":"The plan itself is not bad."}]'::jsonb),
    ('6ac6048a-1018-41ed-9443-e0c514d9fa90'::uuid,ARRAY['(i) それなりに {V/Adjective(い/な)/Noun+Copula}']::text[],ARRAY['Use this construction to express A phrase representing the idea that someone/something does something or is in a state in his/her/its own way, or in a way suitable to the situation or generally expected from the situation.. A phrase representing the idea that someone/something does something or is in a state in his/her/its own way, or in a way suitable to the situation or generally expected from the situation.']::text[],ARRAY['【Related Expression: なりに/の】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"天才と言われる人にはそれなりの苦しみがあると思う。","japanese_furigana":"天才と言われる人にはそれなりの苦しみがあると思う。","english":"I think people who are called geniuses suffer in their own way."},{"japanese":"クラシックもジャズもロックも、聞いてみればみなそれなりに面白い。","japanese_furigana":"クラシックもジャズもロックも、聞いてみればみなそれなりに面白い。","english":"If you (really) listen to classical music, jazz and rock, each of them is interesting in its own way."}]'::jsonb),
    ('a391ce99-60b5-477f-a2bf-d25a7ad6d01e'::uuid,ARRAY['(1) {Adjective な stem/ N} だい']::text[],ARRAY['Use this construction to express A sentence final particle which indicates an interrogative word question in informal male speech.. A sentence final particle which indicates an interrogative word question in informal male speech.']::text[],ARRAY['【Related Expression: か2; かい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"どこが静かだい。","japanese_furigana":"どこが静かだい。","english":"What place is quiet?"},{"japanese":"誰が行くんだい。","japanese_furigana":"誰が行くんだい。","english":"Who is going?"}]'::jsonb),
    ('84474e23-e789-4e76-ba2b-a7481beb59c5'::uuid,ARRAY['(i) Vinformal だけあって']::text[],ARRAY['Use this construction to express A phrase that means “and as one would expect” or “for good reason”.. A phrase that means “and as one would expect” or “for good reason”.']::text[],ARRAY['【Related Expression: だけのことはあって; だけに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は人気女優だけあってすごいうちに住んでいる。","japanese_furigana":"彼女は人気女優だけあってすごいうちに住んでいる。","english":"She is a popular actress and, as one would expect, she lives in a splendid house."},{"japanese":"聡子は小さい時からバレエをしているだけあって体が柔らかい。","japanese_furigana":"聡子は小さい時からバレエをしているだけあって体が柔らかい。","english":"Satoko has practiced ballet since she was a child, so naturally she is limber."}]'::jsonb),
    ('d0d67bba-ffdf-411d-b831-d46839f21d90'::uuid,ARRAY['V informal だけで']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that just doing something is enough for something.. A phrase which expresses the idea that just doing something is enough for something.']::text[],ARRAY['The core sense is A phrase which expresses the idea that just doing something is enough for something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"君はここに座っているだけでよい。","japanese_furigana":"君はここに座っているだけでよい。","english":"You can just sit (literally: be sitting) here."},{"japanese":"私は筆跡を見ただけで誰が書いたか分かった。","japanese_furigana":"私は筆跡を見ただけで誰が書いたか分かった。","english":"I knew who wrote it just by looking at the handwriting."}]'::jsonb),
    ('13a9ddcb-84dd-4896-a1bf-dd63693e72b7'::uuid,ARRAY['(i) Vinformal だけに']::text[],ARRAY['Use this construction to express A phrase that carries the idea “as one would expect”.. A phrase that carries the idea “as one would expect”.']::text[],ARRAY['【Related Expression: だけあって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ビルは元フットボール選手だけに足が速い。","japanese_furigana":"ビルは元フットボール選手だけに足が速い。","english":"Bill used be a football player and, as one would expect, he runs fast."},{"japanese":"ホワイトさんは長い間日本に住んでいただけに日本のことをよく知っている。","japanese_furigana":"ホワイトさんは長い間日本に住んでいただけに日本のことをよく知っている。","english":"Mr. White lived in Japan for a long time, so naturally he is very familiar with things related to Japan."}]'::jsonb),
    ('af104c93-e5ca-4862-a259-dbeb03fc89bb'::uuid,ARRAY['(i) {V/Adjective い}informal だけのことはある']::text[],ARRAY['Use this construction to express A phrase expressing an evaluative comment regarding how something is contributing to an expected, remarkable result.. A phrase expressing an evaluative comment regarding how something is contributing to an expected, remarkable result.']::text[],ARRAY['【Related Expression: だけあって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"明子は韓国語がとても上手だ。さすがに二年間ソウル大学に留学していただけのことはある。","japanese_furigana":"明子は韓国語がとても上手だ。さすがに二年間ソウル大学に留学していただけのことはある。","english":"Akiko is very good at Korean. She didn''t study at Seoul National University for two years for nothing."},{"japanese":"毎日一キロ以上水泳をしてきただけのことはあって、彼は九十歳の今もかくしゃくとしている。","japanese_furigana":"毎日一キロ以上水泳をしてきただけのことはあって、彼は九十歳の今もかくしゃくとしている。","english":"He has been swimming more than 1 kilometre every day. No wonder he is still in such good shape at 90 (years old)."}]'::jsonb),
    ('429d3b9a-549a-4d24-8c2b-9c064cd3aa91'::uuid,ARRAY['Sinformal past ことがある']::text[],ARRAY['Use this construction to express There was a time when ~. There was a time when ~']::text[],ARRAY['The core sense is There was a time when ~; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私はヨーロッパへ行ったことがある・あります。","japanese_furigana":"私はヨーロッパへ行ったことがある・あります。","english":"I have been to Europe."},{"japanese":"レタスがとても高かったことがある・あります。","japanese_furigana":"レタスがとても高かったことがある・あります。","english":"There was a time when lettuce was very expensive."}]'::jsonb),
    ('ad123836-ba29-4f70-adf8-b7594ee429a7'::uuid,ARRAY['(i) だって {V/Adjective い} Informal んだ({もの/もん})']::text[],ARRAY['Use this construction to express A conjunction that indicates a reason.. A conjunction that indicates a reason.']::text[],ARRAY['The core sense is A conjunction that indicates a reason.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"A:どうして会ってくれないの？B:だって、僕、今日忙しいんだ。","japanese_furigana":"A:どうして会ってくれないの？B:だって、僕、今日忙しいんだ。","english":"A: Why won''t you see me? B: ''Cause I''m busy today."},{"japanese":"A:母：さや、どうしてもっとご飯食べないの。B:さや：だっておなか、空いていないもん。","japanese_furigana":"A:母：さや、どうしてもっとご飯食べないの。B:さや：だっておなか、空いていないもん。","english":"Mother: Saya, how come you aren''t eating more? Saya: ''Cause I''m not hungry."}]'::jsonb),
    ('9bea0d61-791e-4cbf-9548-fd08c598b461'::uuid,ARRAY['(i) Noun (Particle) だって']::text[],ARRAY['Use this construction to express A particle meaning “too” or “even”.. A particle meaning “too” or “even”.']::text[],ARRAY['【Related Expression: も; でも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この翻訳なら私にだってできます。","japanese_furigana":"この翻訳なら私にだってできます。","english":"(i) I could do this translation, too. (literally: If it''s this translation, I can do it, too. (ii) Even I could do this translation. (literally: If it''s this translation, even I can do it."},{"japanese":"数多いお客さんの中には難しい人だっている。","japanese_furigana":"数多いお客さんの中には難しい人だっている。","english":"In a large group of customers, there will be difficult people(, too)."}]'::jsonb),
    ('434bd97e-9320-4c61-beed-e57a47b7a6af'::uuid,ARRAY['(i) Vinformal nonpast だに']::text[],ARRAY['Use this construction to express A particle indicating that something expressed by the preceding verb alone produces a certain feeling or the meaning “(not) even doing something; doesn’t even occur”.. A particle indicating that something expressed by the preceding verb alone produces a certain feeling or the meaning “(not) even doing something; doesn’t even occur”.']::text[],ARRAY['【Related Expression: だけでも; さえ; すら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あの時の大きな失敗は思い出すだに恥ずかしい。","japanese_furigana":"あの時の大きな失敗は思い出すだに恥ずかしい。","english":"Just remembering the big mistake I made at that time makes me feel embarrassed."},{"japanese":"イチローが、８４年間続いたジョージ・シスラーの最多安打記録を破るとは想像だにしなかった。","japanese_furigana":"イチローが、８４年間続いたジョージ・シスラーの最多安打記録を破るとは想像だにしなかった。","english":"I couldn''t (literally: didn''t) even imagine that Ichiro would break George Sisler''s 84-year-old record for the most hits in one season."}]'::jsonb),
    ('630b5d93-3837-4601-8d9f-97ac1908bf1f'::uuid,ARRAY['(i) Noun 1 だらけの Noun 2']::text[],ARRAY['Use this construction to express A suffix that indicates that something/someone is covered or filled with something undesirable.. A suffix that indicates that something/someone is covered or filled with something undesirable.']::text[],ARRAY['【Related Expression: まみれ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミスさんはいつも泥だらけの靴を履いています。","japanese_furigana":"スミスさんはいつも泥だらけの靴を履いています。","english":"Mr. Smith is always wearing shoes covered with mud."},{"japanese":"この作文は間違いだらけです。","japanese_furigana":"この作文は間違いだらけです。","english":"This composition is full of mistakes."}]'::jsonb),
    ('82677031-5cca-4f12-a961-33c31d11d440'::uuid,ARRAY['{V/Adjective (い/な) Noun+Copula} informal past り (する)']::text[],ARRAY['Use this construction to express A phrase which expresses an inexhaustive listing of action or states.. A phrase which expresses an inexhaustive listing of action or states.']::text[],ARRAY['The core sense is A phrase which expresses an inexhaustive listing of action or states.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私達は歌ったり躍ったりした・しました。","japanese_furigana":"私達は歌ったり躍ったりした・しました。","english":"We did things like singing and dancing."},{"japanese":"このレストランのステーキは大きかったり小さかったりする・します。","japanese_furigana":"このレストランのステーキは大きかったり小さかったりする・します。","english":"Steaks at this restaurant are sometimes big and sometimes small."}]'::jsonb),
    ('38fd9e9b-4710-4e4f-85ba-930d464705a9'::uuid,ARRAY['Noun たるや']::text[],ARRAY['Use this construction to express A compound particle used to present a subtopic about which the writer provides surprising or impressive information.. A compound particle used to present a subtopic about which the writer provides surprising or impressive information.']::text[],ARRAY['【Related Expression: ときたら; は】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この湖にはここにしかいないという生物がおり、その数たるや50種類を超える。","japanese_furigana":"この湖にはここにしかいないという生物がおり、その数たるや50種類を超える。","english":"There are creatures in this lake that exist only here; in fact, there are more than 50 species."},{"japanese":"ノーベル文学賞はどうやって選考するのだろう。1年間に世界で発表される文学作品の数たるや膨大なものだと思うのだが。","japanese_furigana":"ノーベル文学賞はどうやって選考するのだろう。1年間に世界で発表される文学作品の数たるや膨大なものだと思うのだが。","english":"How do they ever choose (who wins) the Nobel Prize in Literature? (I think) The number of works of literature published around the world in a year must be enormous."}]'::jsonb),
    ('1d533081-634e-40fd-be37-73a826571574'::uuid,ARRAY['(i) Vinformal ついでに']::text[],ARRAY['Use this construction to express A phrase used to express the idea that someone does a second thing at the same time as the first because it takes less time or effort.. A phrase used to express the idea that someone does a second thing at the same time as the first because it takes less time or effort.']::text[],ARRAY['The core sense is A phrase used to express the idea that someone does a second thing at the same time as the first because it takes less time or effort.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"京都へ来たついでに龍安寺の石庭を見に行こうと思っている。","japanese_furigana":"京都へ来たついでに龍安寺の石庭を見に行こうと思っている。","english":"Since I''m in Kyoto, I''m thinking of going to see the rock garden at Ryoanji Temple."},{"japanese":"頼みついでにもう一つお願いしてもいいですか。","japanese_furigana":"頼みついでにもう一つお願いしてもいいですか。","english":"While I''m at it, may I ask another favour of you?"}]'::jsonb),
    ('b0392a7a-e9e0-4ca0-b654-7b812f79d3c4'::uuid,ARRAY['Canonical pattern: 〜って（引用）']::text[],ARRAY['Use this construction to express A colloquial quotation marker.. A colloquial quotation marker.']::text[],ARRAY['【Related Expression: そうだ1; と3】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ジェーンは踊らないって。","japanese_furigana":"ジェーンは踊らないって。","english":"Jane said that she wouldn''t dance / They say that Jane won''t dance."},{"japanese":"今晩は雪が降るって。","japanese_furigana":"今晩は雪が降るって。","english":"They say it''s going to snow tonight."}]'::jsonb),
    ('fa5b5f79-5e89-4bfe-8e14-e4ca7e1c57bd'::uuid,ARRAY['Noun って']::text[],ARRAY['Use this construction to express A colloquial topic-introducer.. A colloquial topic-introducer.']::text[],ARRAY['【Related Expression: (の) は; と言えば (ったら)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"アメリカ人ってフットボールが好きだ・好きですね。","japanese_furigana":"アメリカ人ってフットボールが好きだ・好きですね。","english":"Speaking of Americans, they love football, don''t they?"},{"japanese":"漢字を覚えるって大変だ・大変ですね。","japanese_furigana":"漢字を覚えるって大変だ・大変ですね。","english":"To memorize kanji, it''s terribly hard, isn''t it?"}]'::jsonb),
    ('011c22ad-06bb-4ab6-a77a-5bf541989fca'::uuid,ARRAY['Vます っぱなし']::text[],ARRAY['Use this construction to express An auxiliary which expresses the idea that someone or something keeps doing something, or someone leaves something in an improper state.. An auxiliary which expresses the idea that someone or something keeps doing something, or someone leaves something in an improper state.']::text[],ARRAY['【Related Expression: まま; 続けだ; 続ける】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"新幹線が満員で東京から京都までずっと立ちっぱなしだった。","japanese_furigana":"新幹線が満員で東京から京都までずっと立ちっぱなしだった。","english":"The Shinkansen was so crowded that I stood all the way (literally: kept standing) from Tokyo to Kyoto."},{"japanese":"友達にまだお金を借りっぱなしだ。","japanese_furigana":"友達にまだお金を借りっぱなしだ。","english":"I borrowed money from a friend of mine and still haven''t paid it back."}]'::jsonb),
    ('04842ddd-6566-4156-b550-0ab3663a1db9'::uuid,ARRAY['(i) Noun っぽい']::text[],ARRAY['Use this construction to express A suffix that indicates someone/something has some distinctive characteristic or an attribute identified by a noun, an adjective, or a verb to which the suffix is attached.. A suffix that indicates someone/something has some distinctive characteristic or an attribute identified by a noun, an adjective, or a verb to which the suffix is attached.']::text[],ARRAY['【Related Expression: 風の; らしい; やすい; ような】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"サングラスをかけたやくざっぽい男が街角に立っていた。","japanese_furigana":"サングラスをかけたやくざっぽい男が街角に立っていた。","english":"A yakuza-like man wearing sunglasses was standing at the comer of the street."},{"japanese":"その女の人は確か黒っぽいセーターを着ていたと思います。","japanese_furigana":"その女の人は確か黒っぽいセーターを着ていたと思います。","english":"If I remember correctly, I believe she was wearing a blackish sweater."}]'::jsonb),
    ('b6b68da3-1bc4-48a0-925f-3e63ec8ecd84'::uuid,ARRAY['V て Duration']::text[],ARRAY['Use this construction to express After/since a point in time at which something takes place.. After/since a point in time at which something takes place.']::text[],ARRAY['【Related Expression: てから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こちらにいらっしゃってもう何年になりますか。","japanese_furigana":"こちらにいらっしゃってもう何年になりますか。","english":"How long have you been here / how many years it is since you came here?"},{"japanese":"二人は結婚して二年後に離婚した。","japanese_furigana":"二人は結婚して二年後に離婚した。","english":"The couple got married and two years later they got divorced."}]'::jsonb),
    ('34f04645-e1af-4854-bd5a-3bac82b972f0'::uuid,ARRAY['Canonical pattern: 〜で（原因）']::text[],ARRAY['Use this construction to express A particle (apparently derived from the て form of です) that indicates a weak causal relationship.. A particle (apparently derived from the て form of です) that indicates a weak causal relationship.']::text[],ARRAY['【Related Expression: から3; ので】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山口さんは病気で学校を休んだ・休みました。","japanese_furigana":"山口さんは病気で学校を休んだ・休みました。","english":"Because Mr. Yamaguchi was ill, he didn''t come to school."},{"japanese":"明日は期末試験で大変です。","japanese_furigana":"明日は期末試験で大変です。","english":"I''m having an awful time because of tomorrow''s final exam."}]'::jsonb),
    ('a6e5bb4e-7a29-498b-a150-0f216405e963'::uuid,ARRAY['Canonical pattern: 〜で（基準量）']::text[],ARRAY['Use this construction to express A particle which indicates a basic quantity, for each of which certain amount is associated.. A particle which indicates a basic quantity, for each of which certain amount is associated.']::text[],ARRAY['【Related Expression: につき】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この翻訳は一ページで二千円お払いします。","japanese_furigana":"この翻訳は一ページで二千円お払いします。","english":"We will pay 2.000 yen per page for this translation."},{"japanese":"このアルバイトは一時間で千円払ってくれます。","japanese_furigana":"このアルバイトは一時間で千円払ってくれます。","english":"They will pay me 1,000 yen per hour for this part-time job."}]'::jsonb),
    ('5c80da22-4b96-4425-b1e0-b75f992d2979'::uuid,ARRAY['Canonical pattern: 〜で（場所）']::text[],ARRAY['Use this construction to express A particle which indicates location, except for location of existence.. A particle which indicates location, except for location of existence.']::text[],ARRAY['【Related Expression: に4; に6; を2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私達は喫茶店でコーヒーを飲んだ・飲みました。","japanese_furigana":"私達は喫茶店でコーヒーを飲んだ・飲みました。","english":"We drank coffee at a coffee shop."},{"japanese":"ゆり子はデパートで働いています。","japanese_furigana":"ゆり子はデパートで働いています。","english":"Yuriko is working at a department store."}]'::jsonb),
    ('9be80fce-47a9-4f1b-a41b-e9861f22b6f1'::uuid,ARRAY['Canonical pattern: 〜で（手段）']::text[],ARRAY['Use this construction to express A particle which indicates the use of something for doing something.. A particle which indicates the use of something for doing something.']::text[],ARRAY['【Related Expression: を使って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"宮本さんは毎日バスで会社へ行く・行きます。","japanese_furigana":"宮本さんは毎日バスで会社へ行く・行きます。","english":"Mr. Miyamoto goes to his company by bus everyday."},{"japanese":"日本人は箸でご飯を食べる。","japanese_furigana":"日本人は箸でご飯を食べる。","english":"Japanese people eat rice with chopsticks."}]'::jsonb),
    ('4121a7ff-099a-4f9e-815c-aeab8f1d1002'::uuid,ARRAY['(i) Group 1 verbs']::text[],ARRAY['Use this construction to express The て form ending of verbs and い-type adjectives (The て form ending of な-type adjectives and the て form of the copula is で.). The て form ending of verbs and い-type adjectives (The て form ending of な-type adjectives and the て form of the copula is で.)']::text[],ARRAY['The core sense is The て form ending of verbs and い-type adjectives (The て form ending of な-type adjectives and the て form of the copula is で.); the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ジムは日本へ行って勉強した・勉強しました。","japanese_furigana":"ジムは日本へ行って勉強した・勉強しました。","english":"Jim went to Japan and studied (there)."},{"japanese":"ここのステーキは安くて美味しい・美味しいです。","japanese_furigana":"ここのステーキは安くて美味しい・美味しいです。","english":"Steaks here are inexpensive and delicious."}]'::jsonb),
    ('629b8276-54fa-421d-888f-5f24541b2387'::uuid,ARRAY['Canonical pattern: 〜で（範囲・所要）']::text[],ARRAY['Use this construction to express A particle which indicates the time when something terminates or the amount of time a period of activity has taken.. A particle which indicates the time when something terminates or the amount of time a period of activity has taken.']::text[],ARRAY['【Related Expression: に1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"春学期は五月十日で終わる・終わります。","japanese_furigana":"春学期は五月十日で終わる・終わります。","english":"The spring term ends on May 10."},{"japanese":"このコンサートは十時で終わります。","japanese_furigana":"このコンサートは十時で終わります。","english":"This concert will be over at ten o''clock."}]'::jsonb),
    ('ae5452f5-58ec-4630-8f3d-fb088c54d984'::uuid,ARRAY['(i) Noun であれ']::text[],ARRAY['Use this construction to express A conjunctive phrase that expresses the idea of concession.. A conjunctive phrase that expresses the idea of concession.']::text[],ARRAY['【Related Expression: でも; であっても; であろうが/と】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"たとえ社長であれ、そのような行為は許されない。","japanese_furigana":"たとえ社長であれ、そのような行為は許されない。","english":"Even the (company) president shouldn''t be allowed to do things like that. (literally: Even if it is the president, such conduct should not be allowed."},{"japanese":"どんな問題であれ、必ず私に報告して下さい。","japanese_furigana":"どんな問題であれ、必ず私に報告して下さい。","english":"Whatever kind of problem it may be, please report it to me without fail."}]'::jsonb),
    ('2ca83770-84ee-4147-b83c-13266ee2f198'::uuid,ARRAY['(i) Noun 1 であれ 、Noun 2 であれ']::text[],ARRAY['Use this construction to express A structure that means “no matter which one is the case”. A structure that means “no matter which one is the case”']::text[],ARRAY['【Related Expression: であろうと~であろうと; でも~でも; と言わず~と言わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"男性であれ、女性であれ、人間としての権利は同じはずだ。","japanese_furigana":"男性であれ、女性であれ、人間としての権利は同じはずだ。","english":"Whether one is a man or a woman, one''s rights as a human being should be the same."},{"japanese":"有名であれ、無名であれ、人生は短い。","japanese_furigana":"有名であれ、無名であれ、人生は短い。","english":"No matter if one is famous or nameless, life is short."}]'::jsonb)
), invalid as (
  select grammar_id from enrichment where not public.repository_reference_examples_valid(examples_value)
)
select case when count(*)=0 then true else false end as payloads_valid from invalid;

with enrichment(grammar_id,formation_value,usage_value,nuance_value,examples_value) as (
  values
    ('5cf427a8-b6c3-4e0a-a5cf-41afd12eb714'::uuid,ARRAY['{V/Adjective(い/な)/Noun+copula} て もいい']::text[],ARRAY['Use this construction to express may; it is okay to. Expresses permission.']::text[],ARRAY['【Antonym Expression: はいけない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:ここで煙草を吸ってもいいですか。 B:はい、いいです。","japanese_furigana":"A:ここで煙草を吸ってもいいですか。 B:はい、いいです。","english":"A: May I smoke here? B: Yes, you may."},{"japanese":"高くてもいい・いいです。","japanese_furigana":"高くてもいい・いいです。","english":"It is all right if it''s expensive."}]'::jsonb),
    ('69149182-17db-4697-a3ea-45d583f5895b'::uuid,ARRAY['(i) Vinformal negative なくて Where V is often a potential verb']::text[],ARRAY['Use this construction to express not doing/being and; because not. Negative て-form used to connect states or causes.']::text[],ARRAY['【Related Expression: ないで; ないから; ないので; なくても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"朝七時に起きられなくて会社に遅れた・遅れました。","japanese_furigana":"朝七時に起きられなくて会社に遅れた・遅れました。","english":"I couldn''t get up at seven and was late for work (at my company)."},{"japanese":"先生の説明が分からなくて困りました。","japanese_furigana":"先生の説明が分からなくて困りました。","english":"I didn''t understand the teacher''s explanation and had a difficult time."}]'::jsonb),
    ('debf2b3f-62a5-41ae-a005-5b0f4fd2feb1'::uuid,ARRAY['(i) {V/Adjective い} informal の']::text[],ARRAY['Use this construction to express the act/fact of; nominalizer. Turns a clause into a noun-like unit using の.']::text[],ARRAY['【Related Expression: こと2; の2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語を教えるのは難しい・難しいです。","japanese_furigana":"日本語を教えるのは難しい・難しいです。","english":"Teaching Japanese is difficult."},{"japanese":"私は雪子さんがビールを飲むのを見た・見ました。","japanese_furigana":"私は雪子さんがビールを飲むのを見た・見ました。","english":"I saw Yukiko drink beer."}]'::jsonb),
    ('39353520-bfe0-4d16-8c24-cba5b95d4b6d'::uuid,ARRAY['Canonical pattern: 〜は（主題）']::text[],ARRAY['Use this construction to express as for; topic marker. Marks the topic or a contrastive frame for the sentence.']::text[],ARRAY['【Related Expression: が】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は学生だ・です。","japanese_furigana":"私は学生だ・です。","english":"I am a student."},{"japanese":"杉田さんは行きますが私は行きません。","japanese_furigana":"杉田さんは行きますが私は行きません。","english":"Mr. Sugita will go (there) but I won''t go."}]'::jsonb),
    ('bf848a68-8d58-42e6-a4ef-d75444c20a6f'::uuid,ARRAY['Canonical pattern: あげる']::text[],ARRAY['Use this construction to express give. Giving verb viewed from the giver toward another person.']::text[],ARRAY['【Related Expression: くれる1; (もらう1)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は良子に花をあげた・あげました。","japanese_furigana":"私は良子に花をあげた・あげました。","english":"I gave Yoshiko flowers."},{"japanese":"大野さんは山本さんに本をあげた。","japanese_furigana":"大野さんは山本さんに本をあげた。","english":"Ms. Ono gave Mr. Yamamoto a book."}]'::jsonb),
    ('de8b867c-8c9b-4361-9e71-236ec77466ec'::uuid,ARRAY['Canonical pattern: くれる']::text[],ARRAY['Use this construction to express give me/us. Giving verb for something given to the speaker or speaker''s in-group.']::text[],ARRAY['【Related Expression: あげる1; もらう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"大川さんは（私に）本を呉れた・呉れました。","japanese_furigana":"大川さんは（私に）本を呉れた・呉れました。","english":"Mr. Okawa gave me a book."},{"japanese":"ビルは（君に）何を呉れましたか。","japanese_furigana":"ビルは（君に）何を呉れましたか。","english":"What did Bill give to you?"}]'::jsonb),
    ('1e76f668-b7c2-4c62-8343-fcd71a7df1d7'::uuid,ARRAY['Canonical pattern: もらう']::text[],ARRAY['Use this construction to express receive. Receiving verb viewed from the recipient.']::text[],ARRAY['【Related Expression: くれる1 (あげる1)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"（私は）山本さんに本をもらった・もらいました。","japanese_furigana":"（私は）山本さんに本をもらった・もらいました。","english":"I got a book from Mr. Yamamoto."},{"japanese":"山川さんは橋本さんにウイスキーをもらった。","japanese_furigana":"山川さんは橋本さんにウイスキーをもらった。","english":"Mr. Yamakawa got whiskey from Mr. Hashimoto."}]'::jsonb),
    ('57209ea0-0246-4f0e-b589-26ec1cb9e84e'::uuid,ARRAY['普通形 + けれど／けど']::text[],ARRAY['Use to connect a clause to contrasting information or to soften/background what follows.']::text[],ARRAY['けど is more conversational; けれど and けれども are progressively fuller forms.']::text[],'[{"japanese":"行きたいけど、今日は時間がありません。","japanese_furigana":"[行|い]きたいけど、[今日|きょう]は[時間|じかん]がありません。","english":"I want to go, but I do not have time today."},{"japanese":"この店は小さいけれど、とても人気があります。","japanese_furigana":"この[店|みせ]は[小|ちい]さいけれど、とても[人気|にんき]があります。","english":"This shop is small, but it is very popular."}]'::jsonb),
    ('4de90cb3-dcab-40d9-8e97-01167b5f455c'::uuid,ARRAY['普通形 + 時に']::text[],ARRAY['Use 時に when identifying a particular time point at which an event occurs.']::text[],ARRAY['The particle に highlights the time point more explicitly than 時 without に.']::text[],'[{"japanese":"日本へ行った時に、友達に会いました。","japanese_furigana":"[日本|にほん]へ[行|い]った[時|とき]に、[友達|ともだち]に[会|あ]いました。","english":"When I went to Japan, I met a friend."},{"japanese":"困った時に、この番号に電話してください。","japanese_furigana":"[困|こま]った[時|とき]に、この[番号|ばんごう]に[電話|でんわ]してください。","english":"When you have trouble, please call this number."}]'::jsonb),
    ('d5ddd329-5a91-4a33-ba4e-388321005b6b'::uuid,ARRAY['Vます-stem + に + 行く／来る']::text[],ARRAY['Use a verb stem plus に with a motion verb to state the purpose of going or coming.']::text[],ARRAY['The motion itself is foregrounded, while the verb before に gives its purpose.']::text[],'[{"japanese":"駅へ友達を迎えに行きます。","japanese_furigana":"[駅|えき]へ[友達|ともだち]を[迎|むか]えに[行|い]きます。","english":"I am going to the station to pick up my friend."},{"japanese":"友達が日本へ遊びに来ました。","japanese_furigana":"[友達|ともだち]が[日本|にほん]へ[遊|あそ]びに[来|き]ました。","english":"My friend came to Japan to visit and have fun."}]'::jsonb),
    ('f77c5e9c-7d25-499c-8e15-37f0a204233b'::uuid,ARRAY['(i) Quotation と']::text[],ARRAY['Use this construction to express A particle which marks a quotation, sound or the manner in which someone/something does something.. A particle which marks a quotation, sound or the manner in which someone/something does something.']::text[],ARRAY['The core sense is A particle which marks a quotation, sound or the manner in which someone/something does something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ヒルさんは私に日本語で「こんにちは。」と言った・言いました。","japanese_furigana":"ヒルさんは私に日本語で「こんにちは。」と言った・言いました。","english":"Mr. Hill said to me in Japanese, “Hello!”"},{"japanese":"トムは日本へ行きたいと言っている。","japanese_furigana":"トムは日本へ行きたいと言っている。","english":"Tom says that he wants to go to Japan."}]'::jsonb),
    ('fa94eb9e-5c87-4bb1-94aa-8ca79fa5ad76'::uuid,ARRAY['(i) N(Prt) も N(Prt) も N(Prt) も']::text[],ARRAY['Use this construction to express The repeated use of a particle meaning ‘also’ to list elements belonging to the same part of speech.. The repeated use of a particle meaning ‘also’ to list elements belonging to the same part of speech.']::text[],ARRAY['The core sense is The repeated use of a particle meaning ‘also’ to list elements belonging to the same part of speech.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"田中さんも中山さんもデパートに勤めている・います。","japanese_furigana":"田中さんも中山さんもデパートに勤めている・います。","english":"Both Mr. Tanaka and Mr. Nakayama are working for a department store."},{"japanese":"京都へはバスでも電車でも行ける・行けます。","japanese_furigana":"京都へはバスでも電車でも行ける・行けます。","english":"We can go to Kyoto either by both bus or by electric train."}]'::jsonb),
    ('a7cae4c2-a1b0-47e9-aa3e-9b820a426a76'::uuid,ARRAY['(i) Noun も 私 も I, too/me (as direct object), too']::text[],ARRAY['Use this construction to express A particle which indicates that a proposition about the preceeding element X is also true when another similar proposition is true.. A particle which indicates that a proposition about the preceeding element X is also true when another similar proposition is true.']::text[],ARRAY['The core sense is A particle which indicates that a proposition about the preceeding element X is also true when another similar proposition is true.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私も学生だ・です。","japanese_furigana":"私も学生だ・です。","english":"I, too, am a student."},{"japanese":"私はスペイン語も話す・話します。","japanese_furigana":"私はスペイン語も話す・話します。","english":"I speak Spanish, too."}]'::jsonb),
    ('0d22c6e7-7a70-4e04-992f-596a1586f96c'::uuid,ARRAY['(i) {Vinformal/Vますたい} ものだ']::text[],ARRAY['Use this construction to express The speaker presents some situation as if it were a tangible object.. The speaker presents some situation as if it were a tangible object.']::text[],ARRAY['【Related Expression: から; のだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"A:どうして行かないの？ B:だって、忙しいもの。","japanese_furigana":"A:どうして行かないの？ B:だって、忙しいもの。","english":"A: How come you don''t go there? B: ''Cause I''m busy."},{"japanese":"よくあんな男とデート出来るものだ・です！","japanese_furigana":"よくあんな男とデート出来るものだ・です！","english":"How could you date that kind of guy!"}]'::jsonb),
    ('3d669607-bcf9-472e-8fd1-2979c355083f'::uuid,ARRAY['(i) Noun より']::text[],ARRAY['Use this construction to express A particle which indicates that something/someone is being compared with something/someone.. A particle which indicates that something/someone is being compared with something/someone.']::text[],ARRAY['【Related Expression: 方が~より】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語はスペイン語より（も）面白い・面白いです。","japanese_furigana":"日本語はスペイン語より（も）面白い・面白いです。","english":"Japanese is more interesting than Spanish."},{"japanese":"車で行くほうがバスで行くより（も）安い・安いです。","japanese_furigana":"車で行くほうがバスで行くより（も）安い・安いです。","english":"Going by car is cheaper than going by bus."}]'::jsonb),
    ('f89fdea6-aa2e-40f1-9b27-78d0f8379a63'::uuid,ARRAY['(i) Vvolitional ( っ ) たって']::text[],ARRAY['Use this construction to express The contracted form of と言っても or としても.. The contracted form of と言っても or としても.']::text[],ARRAY['【Related Expression: ようにも(~ない)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一人でしよう(っ)たって、それは無理だ。","japanese_furigana":"一人でしよう(っ)たって、それは無理だ。","english":"You''ll never be able to do it alone! (literally: Even if you try to do it alone, that''s impossible.)"},{"japanese":"今すぐ買いに行く(っ)たって、もう店はみんな閉まっている。","japanese_furigana":"今すぐ買いに行く(っ)たって、もう店はみんな閉まっている。","english":"Even if you wanted to go buy it right now, the stores are all already closed."}]'::jsonb),
    ('b162050f-ccfe-4d88-b6d2-4be509ee41ee'::uuid,ARRAY['(i) Vinformal past って']::text[],ARRAY['Use this construction to express The informal form of ても.. The informal form of ても.']::text[],ARRAY['【Related Expression: ても】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"一人で旅行に行ったって面白くない。","japanese_furigana":"一人で旅行に行ったって面白くない。","english":"It''s not fun traveling (literally: if I travel) alone."},{"japanese":"私は少しくらい高く(っ)たって、質のいいものを買うことにしている。","japanese_furigana":"私は少しくらい高く(っ)たって、質のいいものを買うことにしている。","english":"I make it a rule to buy good quality things even if they are a little more expensive."}]'::jsonb),
    ('ba5912ad-eec1-454a-8ea0-6dba4f334250'::uuid,ARRAY['(i) {V/Adjectiveい}informal nonpast ( と言 ) ってらない']::text[],ARRAY['Use this construction to express A phrase used to express a strong sensation or emotion.. A phrase used to express a strong sensation or emotion.']::text[],ARRAY['【Related Expression: 本当に; て仕方がない; て堪らない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"つまらないミスで試合に負けて悔しい(と言)ったらない。","japanese_furigana":"つまらないミスで試合に負けて悔しい(と言)ったらない。","english":"I''m so mortiﬁed because I lost the game due to a stupid mistake."},{"japanese":"老眼が進んで眼鏡なしでは近くの字が読めないので、不便(と言)ったらない。","japanese_furigana":"老眼が進んで眼鏡なしでは近くの字が読めないので、不便(と言)ったらない。","english":"My farsightedness has gotten worse so I can''t read words up close without my glasses—it''s so inconvenient!"}]'::jsonb),
    ('b920eb08-20c4-4ed9-9415-3582abfdce0a'::uuid,ARRAY['(i) Vinformal past 上で']::text[],ARRAY['Use this construction to express A compound particle that is used to express a preparatory action for a relatively important action.. A compound particle that is used to express a preparatory action for a relatively important action.']::text[],ARRAY['【Related Expression: てから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"よく考えた上で御返事いたします。","japanese_furigana":"よく考えた上で御返事いたします。","english":"I will reply upon careful consideration."},{"japanese":"話し合いの上で結論を出したいと思います。","japanese_furigana":"話し合いの上で結論を出したいと思います。","english":"I would like to draw a conclusion after discussion."}]'::jsonb),
    ('1b87c373-47f3-402e-a5a1-bcaae11e648f'::uuid,ARRAY['あながち ～ ない']::text[],ARRAY['Use this construction to express A structure that indicates that something is not necessarily the way the speaker/writer thought.. A structure that indicates that something is not necessarily the way the speaker/writer thought.']::text[],ARRAY['【Related Expression: 必ずしも~ない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼の推理もあながち間違っていないのかもしれない。","japanese_furigana":"彼の推理もあながち間違っていないのかもしれない。","english":"His guess may not necessarily be wrong."},{"japanese":"バーチャル指揮者ソフトが売れているところを見ると、一度は指揮者になってみたいというのは、あながち僕だけの願望ではないらしい。","japanese_furigana":"バーチャル指揮者ソフトが売れているところを見ると、一度は指揮者になってみたいというのは、あながち僕だけの願望ではないらしい。","english":"Judging by how well virtual conducting software has been selling, apparently I''m not necessarily the only one who''d like to try orchestra conducting at least once in my life."}]'::jsonb),
    ('9357b6ee-2336-465f-a6e5-30fbf29654bc'::uuid,ARRAY['(i) Noun のあまり']::text[],ARRAY['Use this construction to express A conjunction which marks a cause that involves excessive action.. A conjunction which marks a cause that involves excessive action.']::text[],ARRAY['【Related Expression: 過ぎる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私はその晩興奮のあまり寝られなかった。","japanese_furigana":"私はその晩興奮のあまり寝られなかった。","english":"I was so excited that I couldn''t sleep that night."},{"japanese":"この教科書は文法を重視するあまり面白くないものになってしまった。","japanese_furigana":"この教科書は文法を重視するあまり面白くないものになってしまった。","english":"This textbook has turned out to be an uninteresting one because it stressed grammar too much."}]'::jsonb),
    ('d163c4b9-b9c8-4325-a3c5-bc43fc0228c9'::uuid,ARRAY['お Vます する']::text[],ARRAY['Use this construction to express A phrase which humbly expresses the speaker’s politeness to someone when describing the speaker’s action or state that involves or affects that person.. A phrase which humbly expresses the speaker’s politeness to someone when describing the speaker’s action or state that involves or affects that person.']::text[],ARRAY['【Related Expression: お~になる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は先生のスーツケースをお持ちした・しました。","japanese_furigana":"私は先生のスーツケースをお持ちした・しました。","english":"I carried my teacher''s suitcase."},{"japanese":"そのことは私がお話ししましょう。","japanese_furigana":"そのことは私がお話ししましょう。","english":"I will tell you about that matter."}]'::jsonb),
    ('9a04404c-7b01-438b-8e17-4c347aef6a06'::uuid,ARRAY['(i) お Vます だ']::text[],ARRAY['Use this construction to express A phrase which expresses the speaker''s respect for someone when describing that person''s action or state.. A phrase which expresses the speaker''s respect for someone when describing that person''s action or state.']::text[],ARRAY['【Related Expression: お~になる; られる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"お急ぎですか。","japanese_furigana":"お急ぎですか。","english":"Are you in a hurry?"},{"japanese":"今お持ちのカードはもう使えません。","japanese_furigana":"今お持ちのカードはもう使えません。","english":"You can no longer use the card you have now."}]'::jsonb),
    ('1930045d-4ebd-47ca-a77b-ec8eb3007eec'::uuid,ARRAY['(i) お Vます 下さい']::text[],ARRAY['Use this construction to express A phrase which expresses a highly polite request.. A phrase which expresses a highly polite request.']::text[],ARRAY['【Related Expression: 下さい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"少々お待ち下さい。","japanese_furigana":"少々お待ち下さい。","english":"Please wait a moment."},{"japanese":"電話でご注文下さい。","japanese_furigana":"電話でご注文下さい。","english":"Please order by phone."}]'::jsonb),
    ('3ec11a5a-7a2f-4bb5-8cc6-3e764eacbe30'::uuid,ARRAY['(i) {V1/Adjective い1} informal か {V2/Adjective い2} informal か']::text[],ARRAY['Use this construction to express A structure to mark two choices or possibilities about which the speaker/writer is not sure.. A structure to mark two choices or possibilities about which the speaker/writer is not sure.']::text[],ARRAY['The core sense is A structure to mark two choices or possibilities about which the speaker/writer is not sure.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"来年日本へ行けるか行けないかまだ分かりません。","japanese_furigana":"来年日本へ行けるか行けないかまだ分かりません。","english":"I don''t know whether or not I can go to Japan next year."},{"japanese":"傘を駅に置き忘れたのか事務所に忘れたのか、はっきり覚えていません。","japanese_furigana":"傘を駅に置き忘れたのか事務所に忘れたのか、はっきり覚えていません。","english":"I don''t remember well whether I left my umbrella at the station or in my office."}]'::jsonb),
    ('a09036e5-bc82-427e-b982-a1763baba67a'::uuid,ARRAY['Noun 1 が Noun 2 なら ～ (だろう/かもしれない) WhereNoun 1 =Noun 2']::text[],ARRAY['Use this construction to express A structure presenting a counterfactual situation which indicates that things would be better if something were really good or appropriate.. A structure presenting a counterfactual situation which indicates that things would be better if something were really good or appropriate.']::text[],ARRAY['The core sense is A structure presenting a counterfactual situation which indicates that things would be better if something were really good or appropriate.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"会社が会社ならもう少しましな給料を出してくれるのだろうが。","japanese_furigana":"会社が会社ならもう少しましな給料を出してくれるのだろうが。","english":"If my company were a really good one, it would probably pay a bit better salary, but…"},{"japanese":"大学が大学ならもっといい教育が受けられて、いい就職もできたのだろう。","japanese_furigana":"大学が大学ならもっといい教育が受けられて、いい就職もできたのだろう。","english":"If the university had been a really good one, it would have given me a much better education, and I could have gotten a good job."}]'::jsonb),
    ('dae87882-6f27-4550-9f2d-3a9eced46d0b'::uuid,ARRAY['(i) {Verb/Adjective い} か']::text[],ARRAY['Use this construction to express A sentence final particle which indicates that the preceding sentence is interrogative.. A sentence final particle which indicates that the preceding sentence is interrogative.']::text[],ARRAY['【Related Expression: だい (かい)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"よし子は大学へ行く・行きますか。","japanese_furigana":"よし子は大学へ行く・行きますか。","english":"Is Yoshiko going to college?"},{"japanese":"私はテリーにナンシが日本へ行くかと聞いた・聞きました。","japanese_furigana":"私はテリーにナンシが日本へ行くかと聞いた・聞きました。","english":"I asked Terry whether Nancy was going to Japan."}]'::jsonb),
    ('da99d151-1442-4103-96cd-9e48b94bc92d'::uuid,ARRAY['S1 が S2 太郎は泳いだ が 次郎は泳がなかった。 Taro swam but Jiro didn''t swim.']::text[],ARRAY['Use this construction to express A disjunctive coordinate conjunction that combines two sentences.. A disjunctive coordinate conjunction that combines two sentences.']::text[],ARRAY['【Related Expression: だが; だけど; でも; けれども; しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ジョンは来た・来ましたがメアリーは来なかった・来ませんでした。","japanese_furigana":"ジョンは来た・来ましたがメアリーは来なかった・来ませんでした。","english":"John came but Mary didn''t (come)."},{"japanese":"私はビールは飲むが酒は飲まない。","japanese_furigana":"私はビールは飲むが酒は飲まない。","english":"I drink beer but don''t drink sake."}]'::jsonb),
    ('4b0875d7-6c8e-449e-90e2-4df4606f5bc0'::uuid,ARRAY['(i) {V/Adjective い} informal か']::text[],ARRAY['Use this construction to express A particle which marks an alternative.. A particle which marks an alternative.']::text[],ARRAY['【Related Expression: それとも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は電車かバス（か）で行く・行きます。","japanese_furigana":"私は電車かバス（か）で行く・行きます。","english":"I will go either by train or by bus."},{"japanese":"トムが行くかメアリーが行くかどちらかだ・です。","japanese_furigana":"トムが行くかメアリーが行くかどちらかだ・です。","english":"Either Tom will go or Mary will go."}]'::jsonb),
    ('e225bdf5-9c0d-469a-b5e5-3e59b051b3b5'::uuid,ARRAY['(i) {V/Adjective い informal} かい']::text[],ARRAY['Use this construction to express A sentence final particle which marks yes-no questions in informal male speech.. A sentence final particle which marks yes-no questions in informal male speech.']::text[],ARRAY['【Related Expression: だい (か2)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"日本語は面白いかい。","japanese_furigana":"日本語は面白いかい。","english":"Is Japanese interesting?"},{"japanese":"上野さんはアメリカへ行くのかい。","japanese_furigana":"上野さんはアメリカへ行くのかい。","english":"Is Mr. Ueno going to America?"}]'::jsonb),
    ('96b96438-0402-49b5-aeda-fd62fb82e99d'::uuid,ARRAY['(i) {V/Adjective い} informal かしら']::text[],ARRAY['Use this construction to express A sentence final particle which expresses the idea that the female speaker wonders about something.. A sentence final particle which expresses the idea that the female speaker wonders about something.']::text[],ARRAY['The core sense is A sentence final particle which expresses the idea that the female speaker wonders about something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"松本さんは来るかしら。","japanese_furigana":"松本さんは来るかしら。","english":"I wonder if Mr. Matsumoto will come."},{"japanese":"あの先生の授業は面白いかしら。","japanese_furigana":"あの先生の授業は面白いかしら。","english":"I wonder if that teacher''s class is interesting."}]'::jsonb),
    ('62cee8db-44a0-49b5-a680-a1ede1a4f697'::uuid,ARRAY['Canonical pattern: 〜がする（感覚）']::text[],ARRAY['Use this construction to express Something is perceived by someone’s non-visual senses.. Something is perceived by someone’s non-visual senses.']::text[],ARRAY['The core sense is Something is perceived by someone’s non-visual senses.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"子供達の声がした・しました。","japanese_furigana":"子供達の声がした・しました。","english":"I heard children''s voices."},{"japanese":"この魚は変な味がしますね。","japanese_furigana":"この魚は変な味がしますね。","english":"This fish tastes funny, doesn''t it?"}]'::jsonb),
    ('c6f9a075-0dce-42b7-b7e5-6d7cf217d99f'::uuid,ARRAY['Vます がたい']::text[],ARRAY['Use this construction to express An auxiliary adjective which expresses the idea that for someone to do something is virtually impossible or impossible.. An auxiliary adjective which expresses the idea that for someone to do something is virtually impossible or impossible.']::text[],ARRAY['【Related Expression: かねる; 難い; づらい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼のしたことは許しがたい。","japanese_furigana":"彼のしたことは許しがたい。","english":"What he did is unforgivable."},{"japanese":"この旅行は私にとって忘れがたい思い出になるだろう。","japanese_furigana":"この旅行は私にとって忘れがたい思い出になるだろう。","english":"This trip will be an unforgettable one (literally: memory) for me."}]'::jsonb),
    ('c7e0f224-c91f-40b0-a9f7-a7f26da236a0'::uuid,ARRAY['(i) Vます がちだ']::text[],ARRAY['Use this construction to express A suffix to express an undesirable tendency in someone or something.. A suffix to express an undesirable tendency in someone or something.']::text[],ARRAY['【Related Expression: ぎみ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"田中君は最近授業を休みがちだ。","japanese_furigana":"田中君は最近授業を休みがちだ。","english":"Tanaka tends to miss classes these days."},{"japanese":"それは日本に短期間滞在した外国人にありがちな誤解だ。","japanese_furigana":"それは日本に短期間滞在した外国人にありがちな誤解だ。","english":"That''s the kind of misunderstanding which foreigners who stay in Japan for a short period of time are subject to."}]'::jsonb),
    ('cf2f3eb6-fd8d-4548-95a7-cec90bd5acf4'::uuid,ARRAY['(i) Sentence1 informal past かと思うと 、Sentence2 Where the predicate in Sentence2 is non-emotive; the subjects in Sentence1 and Sentence2 are the same']::text[],ARRAY['Use this construction to express A phrase indicating that an action or state in the dependent clause occurs very closely with another action or state in the clause, or causes another action or state in the main clause.. A phrase indicating that an action or state in the dependent clause occurs very closely with another action or state in the clause, or causes another action or state in the main clause.']::text[],ARRAY['【Related Expression: かと思えば; かと思ったら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"最近は、肌寒くなったかと思うと、翌日には暖かくなったりする。","japanese_furigana":"最近は、肌寒くなったかと思うと、翌日には暖かくなったりする。","english":"These days, just when you think it''s gotten chilly, the next day it turns warm again."},{"japanese":"私の書いた小説が出版されるかと思うと、とても嬉しい。","japanese_furigana":"私の書いた小説が出版されるかと思うと、とても嬉しい。","english":"When I think that the novel I wrote will be published, I feel very happy."}]'::jsonb),
    ('ce11ce62-1ae1-4f36-a74e-adb475b698df'::uuid,ARRAY['(i) {V/Vvolitional} informal かな']::text[],ARRAY['Use this construction to express A sentence-final particle that indicates a self-addressed question or a question addressed to an in-group member.. A sentence-final particle that indicates a self-addressed question or a question addressed to an in-group member.']::text[],ARRAY['The core sense is A sentence-final particle that indicates a self-addressed question or a question addressed to an in-group member.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"今週末には何をしようかな。","japanese_furigana":"今週末には何をしようかな。","english":"I wonder what I should do this weekend."},{"japanese":"この問題、君に分かるかな。","japanese_furigana":"この問題、君に分かるかな。","english":"Can you figure out this problem?"}]'::jsonb),
    ('4ae8571c-1f2b-4bb6-b3c0-804d96c8b0d3'::uuid,ARRAY['Vます かねる / かねない']::text[],ARRAY['Use this construction to express An auxiliary expressing that someone cannot do something even if s/he wants to do it.. An auxiliary expressing that someone cannot do something even if s/he wants to do it.']::text[],ARRAY['【Related Expression: がたい; 難い】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"そのことは私には分かりかねますから、部長にお聞きになって下さい。","japanese_furigana":"そのことは私には分かりかねますから、部長にお聞きになって下さい。","english":"I am not in a position to figure out that matter, so please ask the departmental chief."},{"japanese":"あの男はどんな馬鹿なことでもやりかねない。","japanese_furigana":"あの男はどんな馬鹿なことでもやりかねない。","english":"He might (literally: can) do any stupid thing."}]'::jsonb),
    ('60ccb91d-b0b9-4834-8fb4-33e571c38287'::uuid,ARRAY['(i) {まるで/あたかも} {V/Adjective い}informal かのように']::text[],ARRAY['Use this construction to express A conjunctive phrase that forms an adverbial clause which describes the way someone/something appears to the writer, contrary to reality.. A conjunctive phrase that forms an adverbial clause which describes the way someone/something appears to the writer, contrary to reality.']::text[],ARRAY['【Related Expression: かの如く; あたかも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は(まるで)整形手術したかのようにきれいになった。","japanese_furigana":"彼女は(まるで)整形手術したかのようにきれいになった。","english":"Her looks improved (literally: She became beautiful), as though she had undergone cosmetic surgery."},{"japanese":"彼女の病気は年内に治るかのように見えた。","japanese_furigana":"彼女の病気は年内に治るかのように見えた。","english":"It looked as though her illness would be cured before the end of the year."}]'::jsonb),
    ('53964837-dfba-4bf8-a5d1-a22280136f40'::uuid,ARRAY['Noun から Noun にかけて']::text[],ARRAY['Use this construction to express A structure that expresses coverage from one time/location into the other.. A structure that expresses coverage from one time/location into the other.']::text[],ARRAY['【Related Expression: から~まで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の夏、七月から八月にかけて中国大陸を旅行した。","japanese_furigana":"今年の夏、七月から八月にかけて中国大陸を旅行した。","english":"This summer I travelled on the Chinese continent from July through August."},{"japanese":"今週は木曜から金曜にかけて雪が降るでしょう。","japanese_furigana":"今週は木曜から金曜にかけて雪が降るでしょう。","english":"This week it will probably snow from Thursday through Friday."}]'::jsonb),
    ('d8c1770b-646b-4ecc-a3e9-10d9a09d3987'::uuid,ARRAY['Canonical pattern: 〜から〜に至るまで']::text[],ARRAY['Use this construction to express A structure that expresses a wide range of things.. A structure that expresses a wide range of things.']::text[],ARRAY['【Related Expression: から~まで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミスさんは週刊誌から学術書に至るまで、幅広い日本語が読める。","japanese_furigana":"スミスさんは週刊誌から学術書に至るまで、幅広い日本語が読める。","english":"Mr. Smith can read Japanese widely, ranging from weekly magazines to scholastic books."},{"japanese":"その新聞記者は首相の公の生活から私生活に至るまで、何でも知っている。","japanese_furigana":"その新聞記者は首相の公の生活から私生活に至るまで、何でも知っている。","english":"That newspaper reporter knows everything about the premier, ranging from his public life to his private life."}]'::jsonb),
    ('a8462484-a9a2-48e9-8e9c-c71ca6c069bd'::uuid,ARRAY['Vてから 話して から After talking']::text[],ARRAY['Use this construction to express After/since a point in time at which something takes place.. After/since a point in time at which something takes place.']::text[],ARRAY['【Related Expression: あとで; てform of verb】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"雪子は晩ご飯を食べてから映画に行った・行きました。","japanese_furigana":"雪子は晩ご飯を食べてから映画に行った・行きました。","english":"After eating her supper, Yukiko went to a movie."},{"japanese":"私は友達に電話してからうちを出た。","japanese_furigana":"私は友達に電話してからうちを出た。","english":"I left home after making a call to my friend."}]'::jsonb),
    ('75766188-918b-417e-877c-7e5480b40b50'::uuid,ARRAY['Canonical pattern: 〜から（起点・出所）']::text[],ARRAY['Use this construction to express A particle which indicates a starting point or a source.. A particle which indicates a starting point or a source.']::text[],ARRAY['【Related Expression: に3; を3】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"パーティーは八時から始まる・始まります。","japanese_furigana":"パーティーは八時から始まる・始まります。","english":"The party starts from eight o''clock."},{"japanese":"今日の授業は一時から三時までです。","japanese_furigana":"今日の授業は一時から三時までです。","english":"Today''s class is from one o''clock till three o''clock."}]'::jsonb),
    ('8787e77e-286a-4f1f-9b92-fc0e5c239501'::uuid,ARRAY['Noun からして']::text[],ARRAY['Use this construction to express A phrase that singles out something for emphasis or presents something as a basis for judgment.. A phrase that singles out something for emphasis or presents something as a basis for judgment.']::text[],ARRAY['【Related Expression: (で)すら; (で)さえ; からいって; からみて; にしてからが】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"社長からして会社再建の意欲がないんだから、社員の志気が上がらないのは当たり前だ。","japanese_furigana":"社長からして会社再建の意欲がないんだから、社員の志気が上がらないのは当たり前だ。","english":"Even the president has no desire to reconstruct the company; so, of course, his employees'' morale is low."},{"japanese":"あの日本語の話し方からして彼は日本に行ったことがあるに違いない。","japanese_furigana":"あの日本語の話し方からして彼は日本に行ったことがあるに違いない。","english":"Judging from the way he speaks Japanese, he must have been to Japan."}]'::jsonb),
    ('a6bb0848-5d8c-409a-864d-fe3203c62c62'::uuid,ARRAY['(i) (Xは) Noun 1 とNoun 2 (と…)(と) から { なる / なっている }']::text[],ARRAY['Use this construction to express A phrase indicating that something consists of more than one member/constituent.. A phrase indicating that something consists of more than one member/constituent.']::text[],ARRAY['The core sense is A phrase indicating that something consists of more than one member/constituent.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"英語の”relax”はラテン語の”re-”(再び)と”laxare”（緩む）とからなっている。","japanese_furigana":"英語の”relax”はラテン語の”re-”(再び)と”laxare”（緩む）とからなっている。","english":"The English word “relax” consists of the Latin “re-” (again) and “laxare” (to loosen)."},{"japanese":"タンパク質はアミノ酸からなっている。","japanese_furigana":"タンパク質はアミノ酸からなっている。","english":"Proteins are composed of amino acids."}]'::jsonb),
    ('c8aa9292-f124-47d9-9846-6436d040ab7f'::uuid,ARRAY['(i) Vinformal からには']::text[],ARRAY['Use this construction to express A subordinate conjunction meaning “now that,” “once someone does / has done something” or “so long as”.. A subordinate conjunction meaning “now that,” “once someone does / has done something” or “so long as”.']::text[],ARRAY['【Related Expression: 以上(は)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"いったん引き受けたからには最後まで責任をもってやります。","japanese_furigana":"いったん引き受けたからには最後まで責任をもってやります。","english":"Once I take on (the job), I will fulﬁll my responsibility and complete it."},{"japanese":"裁判と言うからには弁護人が不可欠だ。","japanese_furigana":"裁判と言うからには弁護人が不可欠だ。","english":"Since it is a trial, a defence attorney will be indispensable."}]'::jsonb),
    ('4da19598-04e6-430c-b9a7-014ddc3ffb8a'::uuid,ARRAY['Noun から言って']::text[],ARRAY['Use this construction to express A phrase that means either “in terms of” or “judging from”.. A phrase that means either “in terms of” or “judging from”.']::text[],ARRAY['【Related Expression: の点で; からして】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"燃費から言ってこの車は非常に経済的だ。","japanese_furigana":"燃費から言ってこの車は非常に経済的だ。","english":"In terms of gas mileage, this car is extremely economical."},{"japanese":"学生の評価から言って鈴木先生はいい先生に違いない。","japanese_furigana":"学生の評価から言って鈴木先生はいい先生に違いない。","english":"Judging from his student evaluations, Professor Suzuki must be a fine teacher."}]'::jsonb),
    ('1a7b538b-357f-4043-8d7c-1774234fbe7b'::uuid,ARRAY['(i) Adjective い stem かろう']::text[],ARRAY['Use this construction to express An auxiliary indicating the writer''s conjecture which is not based on any particular information or evidence.. An auxiliary indicating the writer''s conjecture which is not based on any particular information or evidence.']::text[],ARRAY['【Related Expression: だろう】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"十年後の自分を予想するのは難しかろう。","japanese_furigana":"十年後の自分を予想するのは難しかろう。","english":"It is probably difficult to predict what one''s self will be like in ten years time."},{"japanese":"この研究を一年で完成するのは極めて難しかろう。","japanese_furigana":"この研究を一年で完成するのは極めて難しかろう。","english":"It is probably extremely difficult to complete this research in one year."}]'::jsonb),
    ('d9b04553-557b-4116-bf8f-61f9d673aeef'::uuid,ARRAY['(i) {V/Adjectiveい} informal か否か']::text[],ARRAY['Use this construction to express A conjunctive phrase indicating that the speaker/writer is wondering whether something is the case or not.. A conjunctive phrase indicating that the speaker/writer is wondering whether something is the case or not.']::text[],ARRAY['【Related Expression: か~ないか; かどうか】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このソフトが役に立つか否かは保証の限りではありません。","japanese_furigana":"このソフトが役に立つか否かは保証の限りではありません。","english":"I cannot say (literally: guarantee) whether this software is useful or not."},{"japanese":"選挙の時に、有権者は候補者が倫理観のある政治家（である）か否かを見抜かなければならない。","japanese_furigana":"選挙の時に、有権者は候補者が倫理観のある政治家（である）か否かを見抜かなければならない。","english":"In an election, the voter has to judge (literally: see through) whether or not a candidate is a politician of integrity."}]'::jsonb),
    ('b39fb22d-8c1c-4d1a-80a8-e9eed6678edb'::uuid,ARRAY['(i) Vinformal きらいがある']::text[],ARRAY['Use this construction to express A phrase indicating that someone or something has an undesirable tendency.. A phrase indicating that someone or something has an undesirable tendency.']::text[],ARRAY['【Related Expression: がち; 傾向がある】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼は物事を単純に考えるきらいがある。","japanese_furigana":"彼は物事を単純に考えるきらいがある。","english":"He has a tendency to think (about things) in simplistic terms."},{"japanese":"彼は独断のきらいがある。","japanese_furigana":"彼は独断のきらいがある。","english":"He is slightly dogmatic (literally: has a touch of dogmatism)."}]'::jsonb),
    ('ac9700a1-2634-4374-8873-14f2e74c7dd0'::uuid,ARRAY['Canonical pattern: 〜くする／〜にする（変化）']::text[],ARRAY['Use this construction to express Someone/something causes a state or action to take place.. Someone/something causes a state or action to take place.']::text[],ARRAY['【Related Expression: なる; やる】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"中山さんはテニスをする・します。","japanese_furigana":"中山さんはテニスをする・します。","english":"Mr. Nakayama plays tennis."},{"japanese":"リーズさんは英語の先生をしている・います。","japanese_furigana":"リーズさんは英語の先生をしている・います。","english":"Mr. Leeds is an English teacher."}]'::jsonb),
    ('5bd04a1b-992a-42ba-875c-973c54116710'::uuid,ARRAY['(i) Noun (particle) こそ']::text[],ARRAY['Use this construction to express A particle which emphasizes a word, phrase, or clause.. A particle which emphasizes a word, phrase, or clause.']::text[],ARRAY['The core sense is A particle which emphasizes a word, phrase, or clause.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"これこそ我々が探し求めていたものだ。","japanese_furigana":"これこそ我々が探し求めていたものだ。","english":"This is the very thing that we''ve been looking for."},{"japanese":"Ａ：どうもすみませんでした。 Ｂ：いいえ、こちらこそすみませんでした。","japanese_furigana":"Ａ：どうもすみませんでした。 Ｂ：いいえ、こちらこそすみませんでした。","english":"A: I''m very sorry. B: No, it''s me who should say that (literally: be sorry)."}]'::jsonb),
    ('8e3d66d6-d71a-4055-8a0c-afec9eb09e95'::uuid,ARRAY['(i) Vinformal nonpast Affirmative/negative こと']::text[],ARRAY['Use this construction to express An auxiliary noun to express a command.. An auxiliary noun to express a command.']::text[],ARRAY['【Related Expression: Imperative】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"発表は十五分以内で行うこと。","japanese_furigana":"発表は十五分以内で行うこと。","english":"Each presentation should be completed (literally: done) within fifteen minutes."},{"japanese":"プールサイドを走らないこと。","japanese_furigana":"プールサイドを走らないこと。","english":"Do not run on the pool deck."}]'::jsonb),
    ('a9fe5ca8-53ff-4c8a-84a1-3523f5f99236'::uuid,ARRAY['(i) V/Adjective い informal nonpast ことがある']::text[],ARRAY['Use this construction to express There are times when ~.. There are times when ~.']::text[],ARRAY['The core sense is There are times when ~.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は朝風呂に入ることがある・あります。","japanese_furigana":"私は朝風呂に入ることがある・あります。","english":"There are times when I take a bath in the morning."},{"japanese":"たかしは朝ご飯を食べずに学校へ行くことがある。","japanese_furigana":"たかしは朝ご飯を食べずに学校へ行くことがある。","english":"There are times when Takashi goes to school without eating breakfast."}]'::jsonb),
    ('dfba262e-3f54-4258-9962-617886f902c7'::uuid,ARRAY['(i) {V/Adjectiveい}informal ことから']::text[],ARRAY['Use this construction to express A phrase that expresses a reason or a cause.. A phrase that expresses a reason or a cause.']::text[],ARRAY['【Related Expression: から; ので; ところから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼はアリバイが成立しなかったことから犯行の嫌疑がかかった。","japanese_furigana":"彼はアリバイが成立しなかったことから犯行の嫌疑がかかった。","english":"Because (literally: from the fact that) he couldn''t establish an alibi, he was suspected of a criminal act."},{"japanese":"妙なことから二人の関係は悪化した。","japanese_furigana":"妙なことから二人の関係は悪化した。","english":"The relationship between the two people deteriorated due to strange circumstances."}]'::jsonb),
    ('afa0634b-45b7-413a-ade8-af59470ee975'::uuid,ARRAY['(i) Nounの ごとし']::text[],ARRAY['Use this construction to express An auxiliary adjective that indicates a resemblance of something/someone to something/someone or indicates how something/someone appears to speaker/writer.. An auxiliary adjective that indicates a resemblance of something/someone to something/someone or indicates how something/someone appears to speaker/writer.']::text[],ARRAY['【Related Expression: ようだ; みたいだ; かのように】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"人生は旅のごとし。","japanese_furigana":"人生は旅のごとし。","english":"Life is like a journey."},{"japanese":"その無謀な行為は火中に飛び込む｛が/かの｝ごとし。","japanese_furigana":"その無謀な行為は火中に飛び込む｛が/かの｝ごとし。","english":"Acting recklessly like that is like jumping into the ﬁre."}]'::jsonb),
    ('629bc104-b1de-495f-b44a-79224a59b649'::uuid,ARRAY['(i) Vinformal nonpast ことで Means']::text[],ARRAY['Use this construction to express A compound particle which indicates a means or a cause.. A compound particle which indicates a means or a cause.']::text[],ARRAY['【Related Expression: から; ことにより; よって; ので; 為(に)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私は週末にゴルフをすることで気分転換を図っています。","japanese_furigana":"私は週末にゴルフをすることで気分転換を図っています。","english":"I try to lift my spirits by playing golf on weekends."},{"japanese":"彼が仲裁の場に出ていったことで事態は余計にこじれた。","japanese_furigana":"彼が仲裁の場に出ていったことで事態は余計にこじれた。","english":"His appearance at the mediation scene complicated the situation even more. (literally: The situation got even more complicated because he appeared at the mediation scene.)"}]'::jsonb),
    ('e079ae47-e27e-4d5d-aed4-ebf207313b74'::uuid,ARRAY['(i) Adjectiveいinformal ことに']::text[],ARRAY['Use this construction to express A phrase that expresses the speaker’s/ writer’s emotion or subjective judgment.. A phrase that expresses the speaker’s/ writer’s emotion or subjective judgment.']::text[],ARRAY['【Related Expression: とは; にも; かな】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"嬉しいことに、今学期は祭日が3日もある。","japanese_furigana":"嬉しいことに、今学期は祭日が3日もある。","english":"I''m glad that there are (as many as) three holidays this term."},{"japanese":"残念なことに、この本は絶版で、普通の本屋では手に入らない。","japanese_furigana":"残念なことに、この本は絶版で、普通の本屋では手に入らない。","english":"To my regret, this book is out of print and cannot be purchased at ordinary bookstores."}]'::jsonb),
    ('837e0548-5f40-4bab-bb33-228bd9c05cd7'::uuid,ARRAY['Sinformal ことによる Exceptions: Adjective な stem なことによる; Noun であることによる']::text[],ARRAY['Use this construction to express A phrase which is used to present an event as the cause of something.. A phrase which is used to present an event as the cause of something.']::text[],ARRAY['【Related Expression: からだ; ためだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今回の失敗は事前の話し合いが不十分だったことによる。","japanese_furigana":"今回の失敗は事前の話し合いが不十分だったことによる。","english":"The failure this time is the result of insufficient discussion beforehand (literally: due to the fact that the preceding discussion was insufficient)."},{"japanese":"進が非行に走ったの両親の愛情が不足していたことによる。","japanese_furigana":"進が非行に走ったの両親の愛情が不足していたことによる。","english":"Susumu''s delinquency was caused by his parents'' lack of affection. (literally: The fact that Susumu ran to juvenile delinquency is because his parents were not affectionate enough with him."}]'::jsonb),
    ('86cb8976-5cc5-4723-b66a-be5d796994f6'::uuid,ARRAY['Vinformal nonpast ことはない Affirmation']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that there is no need to do something or that there is no possibility of doing something.. A phrase which expresses the idea that there is no need to do something or that there is no possibility of doing something.']::text[],ARRAY['【Related Expression: はずはない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あんな男の言うことを聞くことはない。","japanese_furigana":"あんな男の言うことを聞くことはない。","english":"There''s no need to listen to a man like that."},{"japanese":"彼女が今日の会議を忘れることはないと思います。","japanese_furigana":"彼女が今日の会議を忘れることはないと思います。","english":"I think that there is no possibility that she will forget today''s meeting."}]'::jsonb),
    ('c7d29740-b01a-4ffc-987b-6d49e840fa4d'::uuid,ARRAY['(i) Adjective な stem この上ない']::text[],ARRAY['Use this construction to express A phrase that indicates that something or someone is in an extreme state.. A phrase that indicates that something or someone is in an extreme state.']::text[],ARRAY['【Related Expression: 極めて; 非常に; 実に; 極まりない; 限りだ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"生まれたばかりの赤ん坊を車に残して買い物に行くとは非常識この上ない。","japanese_furigana":"生まれたばかりの赤ん坊を車に残して買い物に行くとは非常識この上ない。","english":"It is utterly senseless to leave a newborn baby in the car and go shopping."},{"japanese":"この部屋はクーラーも扇風機もなく、風も全然通らないので、暑いことこの上ない。","japanese_furigana":"この部屋はクーラーも扇風機もなく、風も全然通らないので、暑いことこの上ない。","english":"There is neither an air-conditioner nor a fan in this room, and no breeze, either, so it''s extremely hot in here."}]'::jsonb),
    ('bafff5c6-be8c-48bd-92da-94330711e807'::uuid,ARRAY['Adjective (い/な) stem さ']::text[],ARRAY['Use this construction to express A suffix that makes a noun out of an adjective by attaching it to the stem of an Adj (い) or much less frequently to the stem of an Adj (な). A suffix that makes a noun out of an adjective by attaching it to the stem of an Adj (い) or much less frequently to the stem of an Adj (な)']::text[],ARRAY['【Related Expression: み】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"このうちの広さはちょうどいい・いいです。","japanese_furigana":"このうちの広さはちょうどいい・いいです。","english":"This size of this house is just right."},{"japanese":"富士山の高さはどのぐらいですか。","japanese_furigana":"富士山の高さはどのぐらいですか。","english":"What is the approximate height of Mt. Fuji?"}]'::jsonb),
    ('eb32afae-6b6b-4ac5-a5fa-32e00d0f6740'::uuid,ARRAY['(i) {V/Adjective い}informal さ']::text[],ARRAY['Use this construction to express A sentence final particle used in highly informal speech by male speakers to express different degrees of assertion ranging from a light touch comment up to opposition or imposition.. A sentence final particle used in highly informal speech by male speakers to express different degrees of assertion ranging from a light touch comment up to opposition or imposition.']::text[],ARRAY['【Related Expression: ね; とも; よ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：就職出来るかな。Ｂ：出来るさ。","japanese_furigana":"Ａ：就職出来るかな。Ｂ：出来るさ。","english":"A: I wonder if I can get a job. B: Sure you can."},{"japanese":"Ａ：君は日本語、読めないよね。Ｂ：いや、読めるさ。","japanese_furigana":"Ａ：君は日本語、読めないよね。Ｂ：いや、読めるさ。","english":"A: You cannot read Japanese, right? B: Yeah, sure I can."}]'::jsonb),
    ('a35eb2e9-13fa-4423-80db-e9797fa36475'::uuid,ARRAY['Vneg ざるを得ない']::text[],ARRAY['Use this construction to express An auxiliary indicating that there is no other choice but to do something.. An auxiliary indicating that there is no other choice but to do something.']::text[],ARRAY['【Related Expression: ないわけに(は)いかない; なければならない; しかない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"それは高かったが、教科書だったから買わざるを得なかった。","japanese_furigana":"それは高かったが、教科書だったから買わざるを得なかった。","english":"It was a textbook so I had no choice but to buy it, although it was expensive."},{"japanese":"日本へ行けば、日本の習慣に従わざるを得ない。","japanese_furigana":"日本へ行けば、日本の習慣に従わざるを得ない。","english":"If you go to Japan you cannot help but adapt yourself to Japanese customs."}]'::jsonb),
    ('9ce6068a-0a08-4156-91d6-1bbe8b2e51cc'::uuid,ARRAY['(i) Noun しか']::text[],ARRAY['Use this construction to express A particle which marks an element X when nothing but X makes the expressed proposition true.. A particle which marks an element X when nothing but X makes the expressed proposition true.']::text[],ARRAY['【Related Expression: ばかり; だけ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"戸田さんしか煙草を吸わない・吸いません。","japanese_furigana":"戸田さんしか煙草を吸わない・吸いません。","english":"No one but Mr. Toda smokes."},{"japanese":"私は日本語しか知らない・知りません。","japanese_furigana":"私は日本語しか知らない・知りません。","english":"I know nothing but Japanese."}]'::jsonb),
    ('0d4b02d0-a5e5-4f3b-9d8a-724778b1208e'::uuid,ARRAY['Vて しまう']::text[],ARRAY['Use this construction to express An auxiliary verb which indicates the completion of an action.. An auxiliary verb which indicates the completion of an action.']::text[],ARRAY['【Related Expression:~終わる 】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"池田君は三日でその本を読んでしまった・しまいました。","japanese_furigana":"池田君は三日でその本を読んでしまった・しまいました。","english":"Mr. Ikeda finished reading the book in three days."},{"japanese":"私はルームメートのミルクを飲んでしまった・しまいました。","japanese_furigana":"私はルームメートのミルクを飲んでしまった・しまいました。","english":"I (mistakenly) drank my roommate''s milk."}]'::jsonb),
    ('a7a390c9-1dac-4353-a2d7-07ffba181f6e'::uuid,ARRAY['Vnegative ずして Exception: する→せずして']::text[],ARRAY['Use this construction to express A phrase meaning “without doing something”.. A phrase meaning “without doing something”.']::text[],ARRAY['【Related Expression: ずに; ないで】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"インカ帝国を知らずして南米大陸を語ることはできない。","japanese_furigana":"インカ帝国を知らずして南米大陸を語ることはできない。","english":"You cannot talk about the South American continent without some knowledge of the Inca Empire."},{"japanese":"我々のチームは最終日の最終戦を待たずして優勝が決定した。","japanese_furigana":"我々のチームは最終日の最終戦を待たずして優勝が決定した。","english":"Our team won the championship before (literally: without waiting for) the ﬁnal game on the ﬁnal day."}]'::jsonb),
    ('4f1d5fc0-f8ce-4da4-b5a0-a1b7a3619907'::uuid,ARRAY['Canonical pattern: 〜ずつ']::text[],ARRAY['Use this construction to express A particle that indicates equal distribution of quantity.. A particle that indicates equal distribution of quantity.']::text[],ARRAY['The core sense is A particle that indicates equal distribution of quantity.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私は漢字を毎日五つずつ覚える・覚えます。","japanese_furigana":"私は漢字を毎日五つずつ覚える・覚えます。","english":"I memorize five kanji every day."},{"japanese":"毎月三冊ずつ本を買っています。","japanese_furigana":"毎月三冊ずつ本を買っています。","english":"I''m buying three books per month."}]'::jsonb),
    ('081402d0-4fc3-42af-b2b6-cf605438bd5d'::uuid,ARRAY['(i) Vnegative ずとも Exception: する→せずとも']::text[],ARRAY['Use this construction to express A conjunctive phrase that indicates negative concession: “even if ~ not”.. A conjunctive phrase that indicates negative concession: “even if ~ not”.']::text[],ARRAY['【Related Expression: なくても; ないでも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"今年の夏は涼しいので、エアコンを使わずとも過ごせそうだ。","japanese_furigana":"今年の夏は涼しいので、エアコンを使わずとも過ごせそうだ。","english":"It is cool this summer, so it looks like we can get by without using the air-conditioner."},{"japanese":"シカゴには親しい友人が何人かいるので、ホテルに泊まらずともよい。","japanese_furigana":"シカゴには親しい友人が何人かいるので、ホテルに泊まらずともよい。","english":"Because I have several close friends in Chicago, I don''t have to stay at a hotel."}]'::jsonb),
    ('626a3076-4715-4f2d-8751-c9ae557b5e6c'::uuid,ARRAY['Vnegative ずにはおかない Exception: する→せずにはおかない']::text[],ARRAY['Use this construction to express A phrase that expresses the idea that someone/something necessarily or naturally causes something to happen.. A phrase that expresses the idea that someone/something necessarily or naturally causes something to happen.']::text[],ARRAY['【Related Expression: 必ず; 間違いなく; 絶対に; ずにはおられない/おれない/いられない】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"技術の発達は社会環境の変化をもたらさずにはおかない。","japanese_furigana":"技術の発達は社会環境の変化をもたらさずにはおかない。","english":"Technological advancements are bound to bring about changes to social environments."},{"japanese":"コンピュータの普及とインターネット利用の拡大は大きな教育の変革を促さずにはおかない。","japanese_furigana":"コンピュータの普及とインターネット利用の拡大は大きな教育の変革を促さずにはおかない。","english":"The spread of computers and the expansion of Internet use are bound to promote big changes in education."}]'::jsonb),
    ('9ca85fa3-73af-40e8-9b25-f4ff054c79bd'::uuid,ARRAY['{V/Adjective い} informal ぞ']::text[],ARRAY['Use this construction to express A sentence final particle that emphasises a male speaker''s emotion about something in his monologue or his strong desire to draw someone else''s attention.. A sentence final particle that emphasises a male speaker''s emotion about something in his monologue or his strong desire to draw someone else''s attention.']::text[],ARRAY['【Related Expression: よ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あれ、財布がどこかへ行ってしまったぞ。","japanese_furigana":"あれ、財布がどこかへ行ってしまったぞ。","english":"Hey, my purse has gone somewhere!"},{"japanese":"急がないとバスに乗り遅れるぞ。","japanese_furigana":"急がないとバスに乗り遅れるぞ。","english":"If you don''t hurry, you''ll be late for the bus, you know."}]'::jsonb),
    ('7b57533c-6399-4457-b9d7-db0f2da13b71'::uuid,ARRAY['(i) A: Sentence1']::text[],ARRAY['Use this construction to express A structure which expresses that the speaker/writer cannot easily accept the corollary from the preceding statement owing to some circumstances, although he feels like accepting it. A structure which expresses that the speaker/writer cannot easily accept the corollary from the preceding statement owing to some circumstances, although he feels like accepting it']::text[],ARRAY['【Related Expression: (そう)ですが; けれど(も); しかし】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"Ａ：魚が体にいいそうですよ。Ｂ：そうかと言って、毎日魚ばかりを食べているわけにもいかないでしょう。","japanese_furigana":"Ａ：魚が体にいいそうですよ。Ｂ：そうかと言って、毎日魚ばかりを食べているわけにもいかないでしょう。","english":"A: I hear that fish is good for your health. B: But we couldn''t eat just fish every day, you know."},{"japanese":"アメリカの方が土地も家も安いが、そうかと言って、簡単に移住するわけにもいかない。","japanese_furigana":"アメリカの方が土地も家も安いが、そうかと言って、簡単に移住するわけにもいかない。","english":"Land and housing are less expensive in America, but we cannot easily immigrate."}]'::jsonb),
    ('cbeb6c0c-0215-406a-99bf-e1da1279b4bb'::uuid,ARRAY['Vます そうになる']::text[],ARRAY['Use this construction to express A phrase expressing that something almost happens.. A phrase expressing that something almost happens.']::text[],ARRAY['【Related Expression: もう少し; ちょっとで~するところ(だった)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"冷たい雨の中を傘もささないで歩いていたら、風邪を引きそうになった。","japanese_furigana":"冷たい雨の中を傘もささないで歩いていたら、風邪を引きそうになった。","english":"While walking in the cold rain without using an umbrella, I almost caught a cold."},{"japanese":"私は子供の時、プールで危うく溺れそうになったことがある。","japanese_furigana":"私は子供の時、プールで危うく溺れそうになったことがある。","english":"When I was a child I almost drowned in a swimming pool."}]'::jsonb),
    ('3fb4ca26-f9f4-4433-84cd-6818d7adade3'::uuid,ARRAY['(i) Noun そのもの']::text[],ARRAY['Use this construction to express A phrase used to refer strictly to the preceding noun (phrase) or adjective.. A phrase used to refer strictly to the preceding noun (phrase) or adjective.']::text[],ARRAY['【Related Expression: 自体; 自身】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"マイナス思考ばかりしていると、人生そのものが駄目になる。","japanese_furigana":"マイナス思考ばかりしていると、人生そのものが駄目になる。","english":"If you remain a negative thinker, your life itself will be ruined."},{"japanese":"企画そのものは悪くない。","japanese_furigana":"企画そのものは悪くない。","english":"The plan itself is not bad."}]'::jsonb),
    ('6ac6048a-1018-41ed-9443-e0c514d9fa90'::uuid,ARRAY['(i) それなりに {V/Adjective(い/な)/Noun+Copula}']::text[],ARRAY['Use this construction to express A phrase representing the idea that someone/something does something or is in a state in his/her/its own way, or in a way suitable to the situation or generally expected from the situation.. A phrase representing the idea that someone/something does something or is in a state in his/her/its own way, or in a way suitable to the situation or generally expected from the situation.']::text[],ARRAY['【Related Expression: なりに/の】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"天才と言われる人にはそれなりの苦しみがあると思う。","japanese_furigana":"天才と言われる人にはそれなりの苦しみがあると思う。","english":"I think people who are called geniuses suffer in their own way."},{"japanese":"クラシックもジャズもロックも、聞いてみればみなそれなりに面白い。","japanese_furigana":"クラシックもジャズもロックも、聞いてみればみなそれなりに面白い。","english":"If you (really) listen to classical music, jazz and rock, each of them is interesting in its own way."}]'::jsonb),
    ('a391ce99-60b5-477f-a2bf-d25a7ad6d01e'::uuid,ARRAY['(1) {Adjective な stem/ N} だい']::text[],ARRAY['Use this construction to express A sentence final particle which indicates an interrogative word question in informal male speech.. A sentence final particle which indicates an interrogative word question in informal male speech.']::text[],ARRAY['【Related Expression: か2; かい】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"どこが静かだい。","japanese_furigana":"どこが静かだい。","english":"What place is quiet?"},{"japanese":"誰が行くんだい。","japanese_furigana":"誰が行くんだい。","english":"Who is going?"}]'::jsonb),
    ('84474e23-e789-4e76-ba2b-a7481beb59c5'::uuid,ARRAY['(i) Vinformal だけあって']::text[],ARRAY['Use this construction to express A phrase that means “and as one would expect” or “for good reason”.. A phrase that means “and as one would expect” or “for good reason”.']::text[],ARRAY['【Related Expression: だけのことはあって; だけに】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"彼女は人気女優だけあってすごいうちに住んでいる。","japanese_furigana":"彼女は人気女優だけあってすごいうちに住んでいる。","english":"She is a popular actress and, as one would expect, she lives in a splendid house."},{"japanese":"聡子は小さい時からバレエをしているだけあって体が柔らかい。","japanese_furigana":"聡子は小さい時からバレエをしているだけあって体が柔らかい。","english":"Satoko has practiced ballet since she was a child, so naturally she is limber."}]'::jsonb),
    ('d0d67bba-ffdf-411d-b831-d46839f21d90'::uuid,ARRAY['V informal だけで']::text[],ARRAY['Use this construction to express A phrase which expresses the idea that just doing something is enough for something.. A phrase which expresses the idea that just doing something is enough for something.']::text[],ARRAY['The core sense is A phrase which expresses the idea that just doing something is enough for something.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"君はここに座っているだけでよい。","japanese_furigana":"君はここに座っているだけでよい。","english":"You can just sit (literally: be sitting) here."},{"japanese":"私は筆跡を見ただけで誰が書いたか分かった。","japanese_furigana":"私は筆跡を見ただけで誰が書いたか分かった。","english":"I knew who wrote it just by looking at the handwriting."}]'::jsonb),
    ('13a9ddcb-84dd-4896-a1bf-dd63693e72b7'::uuid,ARRAY['(i) Vinformal だけに']::text[],ARRAY['Use this construction to express A phrase that carries the idea “as one would expect”.. A phrase that carries the idea “as one would expect”.']::text[],ARRAY['【Related Expression: だけあって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ビルは元フットボール選手だけに足が速い。","japanese_furigana":"ビルは元フットボール選手だけに足が速い。","english":"Bill used be a football player and, as one would expect, he runs fast."},{"japanese":"ホワイトさんは長い間日本に住んでいただけに日本のことをよく知っている。","japanese_furigana":"ホワイトさんは長い間日本に住んでいただけに日本のことをよく知っている。","english":"Mr. White lived in Japan for a long time, so naturally he is very familiar with things related to Japan."}]'::jsonb),
    ('af104c93-e5ca-4862-a259-dbeb03fc89bb'::uuid,ARRAY['(i) {V/Adjective い}informal だけのことはある']::text[],ARRAY['Use this construction to express A phrase expressing an evaluative comment regarding how something is contributing to an expected, remarkable result.. A phrase expressing an evaluative comment regarding how something is contributing to an expected, remarkable result.']::text[],ARRAY['【Related Expression: だけあって】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"明子は韓国語がとても上手だ。さすがに二年間ソウル大学に留学していただけのことはある。","japanese_furigana":"明子は韓国語がとても上手だ。さすがに二年間ソウル大学に留学していただけのことはある。","english":"Akiko is very good at Korean. She didn''t study at Seoul National University for two years for nothing."},{"japanese":"毎日一キロ以上水泳をしてきただけのことはあって、彼は九十歳の今もかくしゃくとしている。","japanese_furigana":"毎日一キロ以上水泳をしてきただけのことはあって、彼は九十歳の今もかくしゃくとしている。","english":"He has been swimming more than 1 kilometre every day. No wonder he is still in such good shape at 90 (years old)."}]'::jsonb),
    ('429d3b9a-549a-4d24-8c2b-9c064cd3aa91'::uuid,ARRAY['Sinformal past ことがある']::text[],ARRAY['Use this construction to express There was a time when ~. There was a time when ~']::text[],ARRAY['The core sense is There was a time when ~; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私はヨーロッパへ行ったことがある・あります。","japanese_furigana":"私はヨーロッパへ行ったことがある・あります。","english":"I have been to Europe."},{"japanese":"レタスがとても高かったことがある・あります。","japanese_furigana":"レタスがとても高かったことがある・あります。","english":"There was a time when lettuce was very expensive."}]'::jsonb),
    ('ad123836-ba29-4f70-adf8-b7594ee429a7'::uuid,ARRAY['(i) だって {V/Adjective い} Informal んだ({もの/もん})']::text[],ARRAY['Use this construction to express A conjunction that indicates a reason.. A conjunction that indicates a reason.']::text[],ARRAY['The core sense is A conjunction that indicates a reason.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"A:どうして会ってくれないの？B:だって、僕、今日忙しいんだ。","japanese_furigana":"A:どうして会ってくれないの？B:だって、僕、今日忙しいんだ。","english":"A: Why won''t you see me? B: ''Cause I''m busy today."},{"japanese":"A:母：さや、どうしてもっとご飯食べないの。B:さや：だっておなか、空いていないもん。","japanese_furigana":"A:母：さや、どうしてもっとご飯食べないの。B:さや：だっておなか、空いていないもん。","english":"Mother: Saya, how come you aren''t eating more? Saya: ''Cause I''m not hungry."}]'::jsonb),
    ('9bea0d61-791e-4cbf-9548-fd08c598b461'::uuid,ARRAY['(i) Noun (Particle) だって']::text[],ARRAY['Use this construction to express A particle meaning “too” or “even”.. A particle meaning “too” or “even”.']::text[],ARRAY['【Related Expression: も; でも】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この翻訳なら私にだってできます。","japanese_furigana":"この翻訳なら私にだってできます。","english":"(i) I could do this translation, too. (literally: If it''s this translation, I can do it, too. (ii) Even I could do this translation. (literally: If it''s this translation, even I can do it."},{"japanese":"数多いお客さんの中には難しい人だっている。","japanese_furigana":"数多いお客さんの中には難しい人だっている。","english":"In a large group of customers, there will be difficult people(, too)."}]'::jsonb),
    ('434bd97e-9320-4c61-beed-e57a47b7a6af'::uuid,ARRAY['(i) Vinformal nonpast だに']::text[],ARRAY['Use this construction to express A particle indicating that something expressed by the preceding verb alone produces a certain feeling or the meaning “(not) even doing something; doesn’t even occur”.. A particle indicating that something expressed by the preceding verb alone produces a certain feeling or the meaning “(not) even doing something; doesn’t even occur”.']::text[],ARRAY['【Related Expression: だけでも; さえ; すら】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"あの時の大きな失敗は思い出すだに恥ずかしい。","japanese_furigana":"あの時の大きな失敗は思い出すだに恥ずかしい。","english":"Just remembering the big mistake I made at that time makes me feel embarrassed."},{"japanese":"イチローが、８４年間続いたジョージ・シスラーの最多安打記録を破るとは想像だにしなかった。","japanese_furigana":"イチローが、８４年間続いたジョージ・シスラーの最多安打記録を破るとは想像だにしなかった。","english":"I couldn''t (literally: didn''t) even imagine that Ichiro would break George Sisler''s 84-year-old record for the most hits in one season."}]'::jsonb),
    ('630b5d93-3837-4601-8d9f-97ac1908bf1f'::uuid,ARRAY['(i) Noun 1 だらけの Noun 2']::text[],ARRAY['Use this construction to express A suffix that indicates that something/someone is covered or filled with something undesirable.. A suffix that indicates that something/someone is covered or filled with something undesirable.']::text[],ARRAY['【Related Expression: まみれ】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"スミスさんはいつも泥だらけの靴を履いています。","japanese_furigana":"スミスさんはいつも泥だらけの靴を履いています。","english":"Mr. Smith is always wearing shoes covered with mud."},{"japanese":"この作文は間違いだらけです。","japanese_furigana":"この作文は間違いだらけです。","english":"This composition is full of mistakes."}]'::jsonb),
    ('82677031-5cca-4f12-a961-33c31d11d440'::uuid,ARRAY['{V/Adjective (い/な) Noun+Copula} informal past り (する)']::text[],ARRAY['Use this construction to express A phrase which expresses an inexhaustive listing of action or states.. A phrase which expresses an inexhaustive listing of action or states.']::text[],ARRAY['The core sense is A phrase which expresses an inexhaustive listing of action or states.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"私達は歌ったり躍ったりした・しました。","japanese_furigana":"私達は歌ったり躍ったりした・しました。","english":"We did things like singing and dancing."},{"japanese":"このレストランのステーキは大きかったり小さかったりする・します。","japanese_furigana":"このレストランのステーキは大きかったり小さかったりする・します。","english":"Steaks at this restaurant are sometimes big and sometimes small."}]'::jsonb),
    ('38fd9e9b-4710-4e4f-85ba-930d464705a9'::uuid,ARRAY['Noun たるや']::text[],ARRAY['Use this construction to express A compound particle used to present a subtopic about which the writer provides surprising or impressive information.. A compound particle used to present a subtopic about which the writer provides surprising or impressive information.']::text[],ARRAY['【Related Expression: ときたら; は】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この湖にはここにしかいないという生物がおり、その数たるや50種類を超える。","japanese_furigana":"この湖にはここにしかいないという生物がおり、その数たるや50種類を超える。","english":"There are creatures in this lake that exist only here; in fact, there are more than 50 species."},{"japanese":"ノーベル文学賞はどうやって選考するのだろう。1年間に世界で発表される文学作品の数たるや膨大なものだと思うのだが。","japanese_furigana":"ノーベル文学賞はどうやって選考するのだろう。1年間に世界で発表される文学作品の数たるや膨大なものだと思うのだが。","english":"How do they ever choose (who wins) the Nobel Prize in Literature? (I think) The number of works of literature published around the world in a year must be enormous."}]'::jsonb),
    ('1d533081-634e-40fd-be37-73a826571574'::uuid,ARRAY['(i) Vinformal ついでに']::text[],ARRAY['Use this construction to express A phrase used to express the idea that someone does a second thing at the same time as the first because it takes less time or effort.. A phrase used to express the idea that someone does a second thing at the same time as the first because it takes less time or effort.']::text[],ARRAY['The core sense is A phrase used to express the idea that someone does a second thing at the same time as the first because it takes less time or effort.; the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"京都へ来たついでに龍安寺の石庭を見に行こうと思っている。","japanese_furigana":"京都へ来たついでに龍安寺の石庭を見に行こうと思っている。","english":"Since I''m in Kyoto, I''m thinking of going to see the rock garden at Ryoanji Temple."},{"japanese":"頼みついでにもう一つお願いしてもいいですか。","japanese_furigana":"頼みついでにもう一つお願いしてもいいですか。","english":"While I''m at it, may I ask another favour of you?"}]'::jsonb),
    ('b0392a7a-e9e0-4ca0-b654-7b812f79d3c4'::uuid,ARRAY['Canonical pattern: 〜って（引用）']::text[],ARRAY['Use this construction to express A colloquial quotation marker.. A colloquial quotation marker.']::text[],ARRAY['【Related Expression: そうだ1; と3】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"ジェーンは踊らないって。","japanese_furigana":"ジェーンは踊らないって。","english":"Jane said that she wouldn''t dance / They say that Jane won''t dance."},{"japanese":"今晩は雪が降るって。","japanese_furigana":"今晩は雪が降るって。","english":"They say it''s going to snow tonight."}]'::jsonb),
    ('fa5b5f79-5e89-4bfe-8e14-e4ca7e1c57bd'::uuid,ARRAY['Noun って']::text[],ARRAY['Use this construction to express A colloquial topic-introducer.. A colloquial topic-introducer.']::text[],ARRAY['【Related Expression: (の) は; と言えば (ったら)】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"アメリカ人ってフットボールが好きだ・好きですね。","japanese_furigana":"アメリカ人ってフットボールが好きだ・好きですね。","english":"Speaking of Americans, they love football, don''t they?"},{"japanese":"漢字を覚えるって大変だ・大変ですね。","japanese_furigana":"漢字を覚えるって大変だ・大変ですね。","english":"To memorize kanji, it''s terribly hard, isn''t it?"}]'::jsonb),
    ('011c22ad-06bb-4ab6-a77a-5bf541989fca'::uuid,ARRAY['Vます っぱなし']::text[],ARRAY['Use this construction to express An auxiliary which expresses the idea that someone or something keeps doing something, or someone leaves something in an improper state.. An auxiliary which expresses the idea that someone or something keeps doing something, or someone leaves something in an improper state.']::text[],ARRAY['【Related Expression: まま; 続けだ; 続ける】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"新幹線が満員で東京から京都までずっと立ちっぱなしだった。","japanese_furigana":"新幹線が満員で東京から京都までずっと立ちっぱなしだった。","english":"The Shinkansen was so crowded that I stood all the way (literally: kept standing) from Tokyo to Kyoto."},{"japanese":"友達にまだお金を借りっぱなしだ。","japanese_furigana":"友達にまだお金を借りっぱなしだ。","english":"I borrowed money from a friend of mine and still haven''t paid it back."}]'::jsonb),
    ('04842ddd-6566-4156-b550-0ab3663a1db9'::uuid,ARRAY['(i) Noun っぽい']::text[],ARRAY['Use this construction to express A suffix that indicates someone/something has some distinctive characteristic or an attribute identified by a noun, an adjective, or a verb to which the suffix is attached.. A suffix that indicates someone/something has some distinctive characteristic or an attribute identified by a noun, an adjective, or a verb to which the suffix is attached.']::text[],ARRAY['【Related Expression: 風の; らしい; やすい; ような】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"サングラスをかけたやくざっぽい男が街角に立っていた。","japanese_furigana":"サングラスをかけたやくざっぽい男が街角に立っていた。","english":"A yakuza-like man wearing sunglasses was standing at the comer of the street."},{"japanese":"その女の人は確か黒っぽいセーターを着ていたと思います。","japanese_furigana":"その女の人は確か黒っぽいセーターを着ていたと思います。","english":"If I remember correctly, I believe she was wearing a blackish sweater."}]'::jsonb),
    ('b6b68da3-1bc4-48a0-925f-3e63ec8ecd84'::uuid,ARRAY['V て Duration']::text[],ARRAY['Use this construction to express After/since a point in time at which something takes place.. After/since a point in time at which something takes place.']::text[],ARRAY['【Related Expression: てから】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"こちらにいらっしゃってもう何年になりますか。","japanese_furigana":"こちらにいらっしゃってもう何年になりますか。","english":"How long have you been here / how many years it is since you came here?"},{"japanese":"二人は結婚して二年後に離婚した。","japanese_furigana":"二人は結婚して二年後に離婚した。","english":"The couple got married and two years later they got divorced."}]'::jsonb),
    ('34f04645-e1af-4854-bd5a-3bac82b972f0'::uuid,ARRAY['Canonical pattern: 〜で（原因）']::text[],ARRAY['Use this construction to express A particle (apparently derived from the て form of です) that indicates a weak causal relationship.. A particle (apparently derived from the て form of です) that indicates a weak causal relationship.']::text[],ARRAY['【Related Expression: から3; ので】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"山口さんは病気で学校を休んだ・休みました。","japanese_furigana":"山口さんは病気で学校を休んだ・休みました。","english":"Because Mr. Yamaguchi was ill, he didn''t come to school."},{"japanese":"明日は期末試験で大変です。","japanese_furigana":"明日は期末試験で大変です。","english":"I''m having an awful time because of tomorrow''s final exam."}]'::jsonb),
    ('a6e5bb4e-7a29-498b-a150-0f216405e963'::uuid,ARRAY['Canonical pattern: 〜で（基準量）']::text[],ARRAY['Use this construction to express A particle which indicates a basic quantity, for each of which certain amount is associated.. A particle which indicates a basic quantity, for each of which certain amount is associated.']::text[],ARRAY['【Related Expression: につき】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"この翻訳は一ページで二千円お払いします。","japanese_furigana":"この翻訳は一ページで二千円お払いします。","english":"We will pay 2.000 yen per page for this translation."},{"japanese":"このアルバイトは一時間で千円払ってくれます。","japanese_furigana":"このアルバイトは一時間で千円払ってくれます。","english":"They will pay me 1,000 yen per hour for this part-time job."}]'::jsonb),
    ('5c80da22-4b96-4425-b1e0-b75f992d2979'::uuid,ARRAY['Canonical pattern: 〜で（場所）']::text[],ARRAY['Use this construction to express A particle which indicates location, except for location of existence.. A particle which indicates location, except for location of existence.']::text[],ARRAY['【Related Expression: に4; に6; を2】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"私達は喫茶店でコーヒーを飲んだ・飲みました。","japanese_furigana":"私達は喫茶店でコーヒーを飲んだ・飲みました。","english":"We drank coffee at a coffee shop."},{"japanese":"ゆり子はデパートで働いています。","japanese_furigana":"ゆり子はデパートで働いています。","english":"Yuriko is working at a department store."}]'::jsonb),
    ('9be80fce-47a9-4f1b-a41b-e9861f22b6f1'::uuid,ARRAY['Canonical pattern: 〜で（手段）']::text[],ARRAY['Use this construction to express A particle which indicates the use of something for doing something.. A particle which indicates the use of something for doing something.']::text[],ARRAY['【Related Expression: を使って】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"宮本さんは毎日バスで会社へ行く・行きます。","japanese_furigana":"宮本さんは毎日バスで会社へ行く・行きます。","english":"Mr. Miyamoto goes to his company by bus everyday."},{"japanese":"日本人は箸でご飯を食べる。","japanese_furigana":"日本人は箸でご飯を食べる。","english":"Japanese people eat rice with chopsticks."}]'::jsonb),
    ('4121a7ff-099a-4f9e-815c-aeab8f1d1002'::uuid,ARRAY['(i) Group 1 verbs']::text[],ARRAY['Use this construction to express The て form ending of verbs and い-type adjectives (The て form ending of な-type adjectives and the て form of the copula is で.). The て form ending of verbs and い-type adjectives (The て form ending of な-type adjectives and the て form of the copula is で.)']::text[],ARRAY['The core sense is The て form ending of verbs and い-type adjectives (The て form ending of な-type adjectives and the て form of the copula is で.); the exact English rendering depends on the surrounding context.']::text[],'[{"japanese":"ジムは日本へ行って勉強した・勉強しました。","japanese_furigana":"ジムは日本へ行って勉強した・勉強しました。","english":"Jim went to Japan and studied (there)."},{"japanese":"ここのステーキは安くて美味しい・美味しいです。","japanese_furigana":"ここのステーキは安くて美味しい・美味しいです。","english":"Steaks here are inexpensive and delicious."}]'::jsonb),
    ('629b8276-54fa-421d-888f-5f24541b2387'::uuid,ARRAY['Canonical pattern: 〜で（範囲・所要）']::text[],ARRAY['Use this construction to express A particle which indicates the time when something terminates or the amount of time a period of activity has taken.. A particle which indicates the time when something terminates or the amount of time a period of activity has taken.']::text[],ARRAY['【Related Expression: に1】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"春学期は五月十日で終わる・終わります。","japanese_furigana":"春学期は五月十日で終わる・終わります。","english":"The spring term ends on May 10."},{"japanese":"このコンサートは十時で終わります。","japanese_furigana":"このコンサートは十時で終わります。","english":"This concert will be over at ten o''clock."}]'::jsonb),
    ('ae5452f5-58ec-4630-8f3d-fb088c54d984'::uuid,ARRAY['(i) Noun であれ']::text[],ARRAY['Use this construction to express A conjunctive phrase that expresses the idea of concession.. A conjunctive phrase that expresses the idea of concession.']::text[],ARRAY['【Related Expression: でも; であっても; であろうが/と】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"たとえ社長であれ、そのような行為は許されない。","japanese_furigana":"たとえ社長であれ、そのような行為は許されない。","english":"Even the (company) president shouldn''t be allowed to do things like that. (literally: Even if it is the president, such conduct should not be allowed."},{"japanese":"どんな問題であれ、必ず私に報告して下さい。","japanese_furigana":"どんな問題であれ、必ず私に報告して下さい。","english":"Whatever kind of problem it may be, please report it to me without fail."}]'::jsonb),
    ('2ca83770-84ee-4147-b83c-13266ee2f198'::uuid,ARRAY['(i) Noun 1 であれ 、Noun 2 であれ']::text[],ARRAY['Use this construction to express A structure that means “no matter which one is the case”. A structure that means “no matter which one is the case”']::text[],ARRAY['【Related Expression: であろうと~であろうと; でも~でも; と言わず~と言わず】. Compare the linked expressions carefully because the choice depends on form and context.']::text[],'[{"japanese":"男性であれ、女性であれ、人間としての権利は同じはずだ。","japanese_furigana":"男性であれ、女性であれ、人間としての権利は同じはずだ。","english":"Whether one is a man or a woman, one''s rights as a human being should be the same."},{"japanese":"有名であれ、無名であれ、人生は短い。","japanese_furigana":"有名であれ、無名であれ、人生は短い。","english":"No matter if one is famous or nameless, life is short."}]'::jsonb)
)
update public.japanese_grammar_guides g
set formation=case when coalesce(array_length(g.formation,1),0)=0 then e.formation_value else g.formation end,
    usage=case when coalesce(array_length(g.usage,1),0)=0 then e.usage_value else g.usage end,
    nuance=case when coalesce(array_length(g.nuance,1),0)=0 then e.nuance_value else g.nuance end,
    reference_examples=case when jsonb_typeof(coalesce(g.reference_examples,'[]'::jsonb))='array' and jsonb_array_length(coalesce(g.reference_examples,'[]'::jsonb))=0 then e.examples_value else g.reference_examples end,
    updated_at=now()
from enrichment e
where g.id=e.grammar_id and g.user_id=(select user_id from private.app_owner);

commit;
